const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const clone = o => JSON.parse(JSON.stringify(o));
/* v7.67: the server clock. A phone whose clock is off (set an hour ahead by hand, or an old time-zone table) still stamps Egypt's
   real time: NFCLK is filled by nfClockSync (99zzZzZZzzk-srv-clock) only when the phone is really off — otherwise everything stays on
   the phone own clock exactly as before. skew = server − phone (ms) · off = Cairo's UTC offset from the server (minutes). */
const NFCLK = { skew: 0, off: null, at: 0, diff: 0 };
const nfNowMs = () => Date.now() + NFCLK.skew;
const nfWall = () => NFCLK.off == null ? null : new Date(nfNowMs() + NFCLK.off * 60000); /* read with getUTC* */
const nowISO = () => new Date(nfNowMs()).toISOString();
function localISO(d) { const z = new Date(d.getTime() - d.getTimezoneOffset() * 60000); return z.toISOString().slice(0, 10); }
const todayISO = () => { const w = nfWall(); return w ? w.toISOString().slice(0, 10) : localISO(new Date()); };
/* v7.67 (Mahmoud 14 Oct): clock times on screen are 12-hour — «9:20 ص / 6:00 م» in Arabic, «9:20 AM / 6:00 PM» in English.
   Stored values stay «HH:MM» (24 h) and every calculation still uses them; these two only format what is shown.
   fmtTm('21:05') → '9:05 PM' (the Arabic letter for PM in Arabic) · fmtAtTm(iso | Date | ms) → the Egypt clock time of that moment, 12-hour. */
const nfLangEn = () => { try { return I18N.lang === 'en'; } catch (e) { return false; } };
function fmtTm(t) {
  const m = /^\s*(\d{1,2}):(\d{2})/.exec(String(t ?? '')); if (!m) return t == null ? '' : String(t);
  const h = +m[1] % 24; const pm = h >= 12; const en = nfLangEn();
  return `${h % 12 || 12}:${m[2]} ${pm ? (en ? 'PM' : 'م') : (en ? 'AM' : 'ص')}`;
}
/* the Egypt wall clock (HH:MM, 24h — for storage) of any moment: uses the server offset when the phone clock / zone is off */
function nfHM(v) {
  const ms = v instanceof Date ? v.getTime() : typeof v === 'number' ? v : Date.parse(v); if (!isFinite(ms)) return '';
  let h, mi; if (NFCLK.off != null) { const w = new Date(ms + NFCLK.off * 60000); h = w.getUTCHours(); mi = w.getUTCMinutes(); } else { const d = new Date(ms); h = d.getHours(); mi = d.getMinutes(); }
  return `${String(h).padStart(2, '0')}:${String(mi).padStart(2, '0')}`;
}
function fmtAtTm(v) { if (v == null || v === '') return ''; const t = nfHM(v); return t ? fmtTm(t) : ''; }
const addDays = (iso, n) => { const d = new Date(iso + 'T00:00:00'); d.setDate(d.getDate() + n); return localISO(d); };
const fmtDate = iso => iso ? `${iso.slice(8, 10)}/${iso.slice(5, 7)}/${iso.slice(0, 4)}` : '—';
const fmtDateLong = iso => { if (!iso) return '—'; const d = new Date(iso + 'T00:00:00'); return `${AR_DAYS[d.getDay()]} ${+iso.slice(8, 10)} ${AR_MONTHS[+iso.slice(5, 7) - 1]} ${iso.slice(0, 4)}`; };
const fmtMonth = ym => ym ? `${AR_MONTHS[+ym.slice(5, 7) - 1]} ${ym.slice(0, 4)}` : '—';
const fmtMoney = n => (Math.round((+n || 0) * 100) / 100).toLocaleString('en-US', { maximumFractionDigits: 2 });
const fmtNum = n => (+n || 0).toLocaleString('en-US', { maximumFractionDigits: 2 });
const money = n => `<span class="num ltr">${fmtMoney(n)}</span>`;
const sum = (arr, f) => arr.reduce((a, x) => a + (+(f ? f(x) : x) || 0), 0);
const daysBetween = (a, b) => Math.round((new Date(b + 'T00:00:00') - new Date(a + 'T00:00:00')) / 86400000);
function weekOf(iso, start) { const s0 = start ?? (S.settings?.weekStart ?? 6); const d = new Date(iso + 'T00:00:00'); const diff = (d.getDay() - s0 + 7) % 7; const s = addDays(iso, -diff); return [s, addDays(s, 6)]; }
const monthOf = iso => iso.slice(0, 7);
const byId = (col, id) => S.data[col].get(id);
const list = col => { const a = Array.from(S.data[col].values()); return typeof listScope === 'function' ? listScope(col, a) : a; };
const sortBy = (arr, f, desc) => arr.slice().sort((a, b) => { const x = f(a), y = f(b); return (x < y ? -1 : x > y ? 1 : 0) * (desc ? -1 : 1); });
function deepMerge(base, patch) {
  const out = Object.assign({}, base || {});
  for (const k of Object.keys(patch || {})) {
    const v = patch[k];
    if (v && typeof v === 'object' && !Array.isArray(v) && out[k] && typeof out[k] === 'object' && !Array.isArray(out[k])) out[k] = deepMerge(out[k], v);
    else out[k] = v;
  }
  return out;
}
function mergeSettings(saved) {
  const s = Object.assign({}, clone(DEFAULT_SETTINGS), saved || {});
  for (const k of ['brands', 'departments', 'categories', 'units', 'trades']) if (!Array.isArray(s[k]) || !s[k].length) s[k] = clone(DEFAULT_SETTINGS[k]);
  /* v4.4: upholstery merged into the paint department (only when both still carry their default names) */
  const up = s.departments.find(x => x.id === 'uphol'); const pa = s.departments.find(x => x.id === 'paint');
  if (up && pa && up.name === 'التنجيد' && pa.name === 'الدهان') { pa.name = 'الدهانات والتنجيد والقشرة'; s.departments = s.departments.filter(x => x.id !== 'uphol'); (s.brands || []).forEach(b => { if (Array.isArray(b.route)) b.route = b.route.filter(x => x !== 'uphol'); }); }
  const me = s.departments.find(x => x.id === 'metal'); if (me && me.name === 'السمكرة والحام والتشطيب') me.name = 'السمكرة واللحام والتشطيب';
  /* v4.6: commercial / sales department (LOF CRM) */
  if (!s.departments.some(x => x.id === 'sales')) s.departments.push({ id: 'sales', name: 'التجاري والمبيعات', admin: true });
  const al = (s.brands || []).find(b => b.id === 'alu'); if (al && al.name === '90 Aluminum') al.name = 'Ninety Aluminum Fabrication';
  /* v4.4: administrative departments and installation metadata are added to older saved settings */
  DEFAULT_SETTINGS.departments.forEach(dd => { const cur = s.departments.find(x => x.id === dd.id); if (!cur) { if (dd.admin) s.departments.push(clone(dd)); } else { if (dd.install && !cur.install) Object.assign(cur, { install: dd.install, headOf: dd.headOf }); if (dd.admin && !cur.admin) cur.admin = true; } });
  return hrSettingsMerge(s);
}
