function nextWorkerCode() { let n = 0; list('workers').forEach(w => { const x = /^W-(\d+)$/.exec(w.code || ''); if (x) n = Math.max(n, +x[1]); }); return 'W-' + String(n + 1).padStart(3, '0'); }
const attKey = (date, deptId) => `${monthOf(date)}_${deptId}`;
function attendanceFor(date) { const out = {}; const ym = monthOf(date); list('attendance').forEach(doc => { if (doc.month !== ym) return; const rows = (doc.rows || {})[date] || {}; Object.entries(rows).forEach(([wid, r]) => { out[wid] = r; }); }); return out; }
async function setAtt(date, w, patch) { const key = attKey(date, w.deptId || 'none'); await Store.update('attendance', key, { id: key, month: monthOf(date), deptId: w.deptId || 'none', rows: { [date]: { [w.id]: patch } } }); }
/* time helpers: 'HH:MM' <-> minutes */
const tmToMin = t => { const m = /^(\d{1,2}):(\d{2})/.exec(String(t || '').trim()); return m ? (+m[1]) * 60 + (+m[2]) : null; };
