  const map = new Map(); workers.forEach(w => { const k = idx.has(w.deptId) ? w.deptId : ''; if (!map.has(k)) map.set(k, []); map.get(k).push(w); });
  const ord = k => (k === '' ? 1e9 : idx.get(k));
