function tierDays(tiers, mins) { const t = (tiers || []).find(x => mins >= +x.from && mins <= +x.to); return t ? (+t.days || 0) : 0; }
function computeAutoPenalties(w, ym) {
  const rows = attMonthRows(w, ym); const pol = S.settings.policy || {}; const out = []; const today = todayISO();
  const mk = (date, kind, days, minutes, reason) => ({ id: `${ym}_${w.id}_${date}_${kind}`, workerId: w.id, deptId: w.deptId || null, date, month: ym, kind, days, minutes: minutes || 0, amount: 0, auto: true, reason, status: 'active' });
  monthDates(ym).forEach(date => {
    const row = rows[date]; const c = classifyDay(w, date, row); if (!row) return;
    if (c.kind === 'present' || c.kind === 'half') {
      const exc = excused(row);
      if (row.late && !exc.late) { const d = tierDays(pol.lateTiers, +row.late); if (d > 0) out.push(mk(date, 'late', d, +row.late, `تأخير ${row.late} دقيقة`)); }
      if (row.early && !exc.early) { const d = tierDays(pol.earlyTiers, +row.early); if (d > 0) out.push(mk(date, 'early', d, +row.early, `انصراف مبكر ${row.early} دقيقة`)); }
      if (row.in && !row.out && date < today && +pol.missingPunchDays > 0) out.push(mk(date, 'missing', +pol.missingPunchDays, 0, 'لم يسجّل الانصراف'));
    }
    if (c.kind === 'absent') { const ap = typeof absencePenaltyFor === 'function' ? absencePenaltyFor(w, ym, date, pol) : (+pol.absencePenaltyDays > 0 ? { days: +pol.absencePenaltyDays, reason: 'غياب بدون إذن (جزاء إضافي لخصم اليوم)' } : null); if (ap && ap.days > 0) out.push(mk(date, 'absence', ap.days, 0, ap.reason)); }
  });
  return out;
}
async function applyAutoPenalties(ym, workers) {
  let created = 0, removed = 0;
  for (const w of workers) {
    const computed = computeAutoPenalties(w, ym); const ids = new Set(computed.map(p => p.id));
    for (const p of computed) { const ex = byId('penalties', p.id); if (ex && (ex.status === 'waived' || ex.edited)) continue; if (ex && +ex.days === +p.days && +ex.minutes === +p.minutes) continue; await Store.save('penalties', Object.assign({}, ex || {}, p), { silent: true }); created++; }
    for (const ex of list('penalties')) { if (ex.auto && ex.workerId === w.id && ex.month === ym && !ids.has(ex.id) && ex.status !== 'waived' && !ex.edited) { await Store.remove('penalties', ex.id); removed++; } }
  }
  rerender(); return { created, removed };
}
function payrollRow(w, ym) {
  const pol = S.settings.policy || {}; const hpd = +S.settings.hoursPerDay || 8; const otm = +S.settings.otMultiplier || 1.5; const oth = +pol.otHolidayMultiplier || 2;
  const s = hrMonthSummary(w, ym); const dr = dailyRate(w); const hr = dr / hpd; const monthly = w.contract === 'monthly';
  const basic = monthly ? (+w.basic || 0) : 0; const allow = monthly ? (+w.allowances || 0) : 0;
  const paidDays = s.present + s.half * 0.5 + (!monthly && pol.dailyPaidLeave ? s.leavePaid : 0);
  const gross = monthly ? basic + allow : paidDays * dr;
  const absenceDays = monthly ? (s.absent + s.leaveUnpaid + s.half * 0.5) : 0; const absenceDed = absenceDays * dr;
  const otPay = s.ot * hr * otm + s.otHoliday * hr * oth;
  const pens = list('penalties').filter(p => p.workerId === w.id && p.month === ym && p.status !== 'waived');
  const penDays = sum(pens.filter(p => p.kind !== 'bonus'), p => p.days); const penAmt = sum(pens.filter(p => p.kind !== 'bonus'), p => p.amount); const bonus = sum(pens.filter(p => p.kind === 'bonus'), p => p.amount);
  const penaltyDed = penDays * dr + penAmt;
  const advs = list('advances').filter(a => a.workerId === w.id && a.status !== 'closed' && (a.date || '') <= ym + '-31' && !['topay', 'review'].includes(a.payStatus)); const advanceDed = sum(advs, a => Math.min(+a.monthly || 0, Math.max(0, (+a.amount || 0) - (+a.paid || 0))));
  const net = gross + otPay + bonus - absenceDed - penaltyDed - advanceDed;
  return { wid: w.id, name: w.name, deptId: w.deptId, contract: w.contract || 'daily', dr: r2(dr), basic, allow, paidDays, present: s.present, half: s.half, absent: s.absent, leavePaid: s.leavePaid, leaveUnpaid: s.leaveUnpaid, late: s.late, lateCount: s.lateCount, ot: r2(s.ot), otHoliday: r2(s.otHoliday), otPay: r2(otPay), gross: r2(gross), absenceDays, absenceDed: r2(absenceDed), penDays, penaltyDed: r2(penaltyDed), bonus: r2(bonus), advanceDed: r2(advanceDed), net: r2(net), unrecorded: s.unrecorded, hrs: r2(s.hrs) };
}
function payrollFor(ym, workers) { const locked = byId('payrolls', ym); if (locked && locked.rows) return { locked: true, doc: locked, rows: workers.map(w => locked.rows[w.id]).filter(Boolean) }; return { locked: false, rows: workers.map(w => payrollRow(w, ym)) }; }

/* ---------------- production <-> HR integration ---------------- */
function deptActiveOrders(deptId) { return sortBy(list('orders').filter(o => isOpen(o) && o.status !== 'hold' && (o.stages || {})[deptId]?.status === 'active'), o => o.dueDate || '9'); }
/* base allocation over the department's active orders (part 13 wraps it with project assignments) */
function autoAllocRowBase(w, row, fallbackHours) {
  if (!w || !row || S.settings.policy?.autoAllocate === false) return row;
  if ((row.alloc || []).some(a => !a.auto)) return row;
  const hrs = row.hrs != null ? +row.hrs : (fallbackHours || 0); if (!hrs || !['P', 'H'].includes(row.s)) return row;
  const os = deptActiveOrders(w.deptId).slice(0, 3); if (!os.length) return row;
  const h = r2(hrs / os.length); return Object.assign({}, row, { alloc: os.map(o => ({ orderId: o.id, h, auto: true })) });
}
function laborByWorker(o) {
  const by = {}; let hours = 0, cost = 0;
  list('attendance').forEach(doc => Object.entries(doc.rows || {}).forEach(([date, rows]) => Object.entries(rows).forEach(([wid, r]) => (r.alloc || []).forEach(al => { if (al.orderId !== o.id) return; const w = byId('workers', wid); const h = +al.h || 0; const c = h * (w ? hourlyRate(w) : 0); hours += h; cost += c; const b = by[wid] ||= { w, h: 0, cost: 0, days: 0 }; b.h += h; b.cost += c; b.days++; }))));
  return { hours: r2(hours), cost: r2(cost), by };
}
function monthLabor(ym, deptId) {
  let hours = 0, cost = 0, allocated = 0;
  list('attendance').forEach(doc => { if (doc.month !== ym || (deptId && doc.deptId !== deptId)) return; Object.values(doc.rows || {}).forEach(rows => Object.entries(rows).forEach(([wid, r]) => { const w = byId('workers', wid); if (!w) return; const h = +r.hrs || (['P', 'H'].includes(r.s) ? (r.s === 'H' ? (+S.settings.hoursPerDay || 8) / 2 : (+S.settings.hoursPerDay || 8) + (+r.ot || 0)) : 0); hours += h; cost += h * hourlyRate(w); allocated += sum(r.alloc || [], a => a.h); })); });
  return { hours: r2(hours), cost: r2(cost), allocated: r2(allocated) };
}
