function wireWorkerForm(f) { wireChecks(f); const sh = $('#f-shiftId', f); const wp = $('#f-workplace', f); if (sh && wp) { const sync = () => { const s = (S.settings.shifts || []).find(x => x.id === sh.value); if (s && s.remote) wp.value = 'home'; }; sh.addEventListener('change', sync); wp.addEventListener('change', () => { if (wp.value === 'home') { const r = (S.settings.shifts || []).find(x => x.remote); if (r && !((S.settings.shifts || []).find(x => x.id === sh.value) || {}).remote) sh.value = r.id; } }); }
  const rs = $('#f-role', f); if (rs) rs.addEventListener('change', () => { const h = $('#rolehint', f); if (h) h.textContent = roleHint(rs.value); const sm = $('#rolesees', f); if (sm && typeof roleSeesHTML === 'function') sm.innerHTML = roleSeesHTML(rs.value); const box = $('#accessDeptsBox', f); if (box) box.hidden = rs.value !== 'head'; ['#userBox', '#passBox'].forEach(sel => { const b = $(sel, f); if (b) b.hidden = rs.value === 'none'; }); }); }
