  const ph = normPhone(d.phone), wph = normPhone(d.workPhone); const dup = list('workers').find(x => x.id !== id && x.status !== 'inactive' && ((ph && (normPhone(x.phone) === ph || normPhone(x.workPhone) === ph)) || (wph && (normPhone(x.phone) === wph || normPhone(x.workPhone) === wph)))); if (dup) { toast(`رقم الموبايل مسجّل بالفعل للموظف ${dup.name}`, 'err'); return null; }
  if (canEditHr()) { d.accessDepts = accessDepts; if (d.role === 'admin' && !isAdmin()) d.role = w.role || 'none'; } else { delete d.role; delete d.username; delete d.password; }
  const pw = d.password; delete d.password;
