    const taken = d.username && loginPeople().find(p => normUser(p.username) === d.username && !(p.kind === 'worker' && p.rec.id === id)); if (taken) { toast('اسم المستخدم مستخدم بالفعل', 'err'); return null; }
    if (!w.passHash && !pw && !emp && !(typeof sbOn === 'function' && sbOn())) { toast('اكتب كلمة سر للدخول (6 أحرف على الأقل)', 'err'); return null; }
