ACTIONS.workerNew = () => openModal({ title: 'موظف جديد', wide: true, body: workerForm({}), onOpen: wireWorkerForm, onSubmit: async f => { const doc = await workerFromForm(f, {}); if (!doc) return false; await Store.save('workers', doc); toast('تمت الإضافة'); go('workers/' + doc.id); } });
ACTIONS.workerEdit = id => { const w = byId('workers', id); if (!w) return; openModal({ title: `تعديل ${w.name}`, wide: true, body: workerForm(w), onOpen: wireWorkerForm, extra: isAdmin() ? `<div class="grow"></div><button type="button" class="btn ghost" style="color:var(--crit-ink)" data-action="workerDelete" data-arg="${w.id}">${icon('trash')}حذف</button>` : '', onSubmit: async f => { const doc = await workerFromForm(f, w); if (!doc) return false; await Store.save('workers', doc); toast('تم الحفظ'); } }); };
ACTIONS.workerDelete = async id => { const w = byId('workers', id); if (!w) return; if (!(await confirmDlg(`حذف ${w.name} نهائيًا؟ الأفضل تحويله إلى "ترك العمل" للاحتفاظ بسجلاته.`, 'حذف نهائي'))) return; await Store.remove('workers', id); go('workers'); toast('تم الحذف'); };

