  const rows = attMonthRows(w, ym); const reqs = sortBy(list('requests').filter(r => r.workerId === w.id), r => r.createdAt || '', true);
  const pens = sortBy(list('penalties').filter(p => p.workerId === w.id), p => p.date || '', true); const advs = sortBy(list('advances').filter(a => a.workerId === w.id), a => a.date || '', true);
