    body = `<div class="card tight"><div class="tablewrap"><table><thead><tr><th>الشهر</th><th class="n">أيام مدفوعة</th><th class="n">الإجمالي</th><th class="n">إضافي</th><th class="n">خصومات</th><th class="n">صافي</th><th>الحالة</th><th></th></tr></thead><tbody>${months.map(m => { const pr = payrollFor(m, [w]); const r = pr.rows[0]; if (!r) return ''; return `<tr><td>${fmtMonth(m)}</td><td class="n">${fmtNum(r.paidDays)}</td><td class="n">${fmtMoney(r.gross)}</td><td class="n">${fmtMoney(r.otPay + r.bonus)}</td><td class="n">${fmtMoney(r.absenceDed + r.penaltyDed + r.advanceDed)}</td><td class="n"><b>${fmtMoney(r.net)}</b></td><td>${pr.locked ? '<span class="badge good">معتمد</span>' : '<span class="badge">تقديري</span>'}</td><td class="n"><button class="btn xs" data-action="payslip" data-arg="${m}:${w.id}">${icon('print')}قسيمة</button></td></tr>`; }).join('')}</tbody></table></div></div>`;
