ACTIONS.geoUseMine = async () => { toast('جارٍ تحديد الموقع…'); const p = await getGeo(10000); if (!p) { toast('تعذّر تحديد الموقع — اسمح للمتصفح بالوصول للموقع', 'err'); return; } const la = $('#f-lat'), ln = $('#f-lng'); if (la) la.value = p.lat; if (ln) ln.value = p.lng; toast(`تم: ${p.lat}, ${p.lng} (دقة ${p.acc} م)`); };
/* =====================================================================
   Punch setup per employee: photo · methods (face / PIN / device biometric) ·
   punch zones (factory / assigned work sites with validity period)
   ===================================================================== */
const PUNCH_AT = { auto: 'تلقائي — المصنع، وموقع المشروع فقط أثناء التركيب', factory: 'المصنع فقط', sites: 'مواقع العمل المخصصة له فقط', both: 'المصنع أو مواقع العمل', any: 'بدون قيد موقع' };
const INSTALL_DEPT = id => /^inst/.test(String(id || ''));
const punchMethodsOf = w => Object.assign({ face: true, pin: true, device: true, selfie: true }, (w && w.punchMethods) || {}); // v4.6.2: device biometric (fingerprint / phone face) is standard for everyone
const punchAtOf = w => (w && (w.workplace === 'home' || ((S.settings.shifts || []).find(x => x.id === w.shiftId) || {}).remote)) ? 'any' : (w && w.workplace === 'hq' && (!w.punchAt || w.punchAt === 'auto')) ? 'office' : (w && w.punchAt && PUNCH_AT[w.punchAt]) ? w.punchAt : 'auto';
const avatarHTML = (w, size = 34) => `<div class="avatar" style="width:${size}px;height:${size}px;font-size:${Math.round(size * 0.42)}px">${w && w.photo ? `<img src="${esc(w.photo)}" alt="">` : esc(((w && w.name) || '?').trim().charAt(0))}</div>`;

/* ---------------- zones ---------------- */
function factoryZone() { const g = geoCfg(); return (g.lat != null && g.lat !== '' && g.lng != null && g.lng !== '') ? { id: 'factory', name: 'المصنع', lat: +g.lat, lng: +g.lng, radius: +g.radius || 200 } : null; }
const siteActiveOn = (s, date) => s.active !== false && (!s.from || s.from <= date) && (!s.to || s.to >= date);
function activeSitesFor(w, date) { date = date || todayISO(); return list('sites').filter(s => siteActiveOn(s, date) && (s.workerIds || []).includes(w.id) && s.lat != null && s.lat !== ''); }
function zonesFor(w, date) { /* overridden in part 13 (project zones) */
  const mode = punchAtOf(w); if (mode === 'any') return { unrestricted: true, zones: [] };
  const zones = []; if (mode === 'factory' || mode === 'both') { const f = factoryZone(); if (f) zones.push(f); }
  if (mode === 'sites' || mode === 'both') activeSitesFor(w, date).forEach(s => zones.push({ id: s.id, name: s.name, lat: +s.lat, lng: +s.lng, radius: +s.radius || 50, to: s.to }));
  return { unrestricted: false, zones };
}
function zoneCheckBase(w, pos) {
  const z = zonesFor(w); if (z.unrestricted) return { unrestricted: true, inside: null, zone: null, dist: null };
  if (!z.zones.length) return { noZones: true, inside: null, zone: null, dist: null };
  if (!pos) return { inside: null, zone: null, dist: null, zones: z.zones };
  let best = null; z.zones.forEach(zn => { const dist = Math.round(haversine(pos, zn)); const over = dist - zn.radius - Math.min(30, (pos.acc || 0) * 0.5); if (!best || over < best.over) best = { zone: zn, dist, over, inside: over <= 0 }; });
  return { inside: best.inside, zone: best.zone, dist: best.dist, zones: z.zones };
}
/* replaces the plain factory-only check: zone-aware, only mobile (self) punches are enforced */
let _nzNoticeAt = 0; const isAdminMissingZoneNotice = () => { if (Date.now() - _nzNoticeAt < 3600000) return false; _nzNoticeAt = Date.now(); return true; };
async function punchGeoBase(w, method) {
  const g = geoCfg(); const pos = await getGeo(); const chk = zoneCheck(w || {}, pos);
  const geo = pos ? Object.assign({}, pos, { dist: chk.dist, inside: chk.inside, zone: chk.zone ? chk.zone.name : null }) : null;
  let blocked = false, msg = '';
  if (method === 'self' && g.required !== false && !chk.unrestricted && chk.noZones) { blocked = true; msg = punchAtOf(w) === 'sites' ? 'لا يوجد موقع عمل مخصص لك اليوم — راجع رئيس القسم' : 'موقع المصنع غير محدد في الإعدادات — البصمة موقوفة حتى يضبطه المدير'; if (typeof notifyOwner === 'function' && isAdminMissingZoneNotice()) notifyOwner('البصمة موقوفة: موقع المصنع غير محدد', `${w && w.name ? w.name + ' حاول البصمة و' : ''}لا توجد إحداثيات للمصنع في الإعدادات ← المواقع. اضبطها الآن.`, { id: 'nozone_' + todayISO() }).catch(() => { }); }
  else if (method === 'self' && g.required !== false && !chk.unrestricted && !chk.noZones) {
    if (!pos) { blocked = true; msg = 'تعذّر تحديد موقعك — فعّل خدمة الموقع (GPS) واسمح للمتصفح بالوصول إليه'; }
    else if (chk.poorAcc) { blocked = true; msg = `دقة تحديد الموقع ضعيفة (±${fmtNum(chk.acc)} م والمسموح ±${chk.maxAcc} م) — قف في مكان مكشوف بعيدًا عن الأسقف، وتأكد أن الـGPS مفعّل، ثم أعد المحاولة`; }
    else if (!chk.inside) { blocked = true; msg = `أنت خارج نطاق البصمة — أقرب موقع مسموح: ${chk.zone.name} (على بُعد ${fmtNum(chk.dist)} م، والمسموح ${chk.zone.radius} م)`; }
  }
  return { geo, blocked, msg, chk };
}
function zoneSummary(w) { const z = zonesFor(w); if (z.unrestricted) return 'بدون قيد موقع'; if (!z.zones.length) return punchAtOf(w) === 'sites' ? 'لا يوجد موقع عمل مخصص له الآن' : 'لم تُضبط إحداثيات المصنع بعد'; const txt = z.zones.map(x => `${x.name} (${x.radius} م${x.to ? `، حتى ${fmtDate(x.to)}` : ''})`).join(' · '); return z.projectDay ? `اليوم في موقع المشروع: ${txt}` : txt; }

/* ---------------- Google Maps link / coordinates parsing ---------------- */
function parseCoords(txt) {
  const s = arDigits(txt || '').trim(); if (!s) return null;
  const pats = [/@(-?\d{1,2}\.\d+),(-?\d{1,3}\.\d+)/, /[?&]q=(-?\d{1,2}\.\d+),(-?\d{1,3}\.\d+)/, /!3d(-?\d{1,2}\.\d+)!4d(-?\d{1,3}\.\d+)/, /[?&](?:ll|center|destination)=(-?\d{1,2}\.\d+),(-?\d{1,3}\.\d+)/, /^\s*(-?\d{1,2}\.\d+)\s*[, ]\s*(-?\d{1,3}\.\d+)\s*$/];
  for (const p of pats) { const m = p.exec(s); if (m) return { lat: +m[1], lng: +m[2] }; }
  return null;
}
const mapsLink = (lat, lng) => `https://www.google.com/maps?q=${lat},${lng}`;

/* ---------------- sites page ---------------- */
