/* ---------------- face verification 1:1 (selfie on the employee's phone) ---------------- */
function faceVerifyBase(w, opts = {}) {
  return new Promise(resolve => {
    let done = false; const fin = r => { if (done) return; done = true; stopStream($('#cam')); closeModal(); resolve(r); };
    openModal({ title: opts.title || `التحقق بالوجه — ${w.name}`, sticky: true, footer: `<span class="muted small grow" id="face-hint">انظر إلى الكاميرا بإضاءة جيدة</span><button type="button" class="btn" id="face-cancel">إلغاء</button>`,
      body: `<div class="camwrap"><video id="cam" autoplay muted playsinline></video><div class="camov" id="camov"></div></div><p id="face-status" class="small muted" style="text-align:center;margin-top:10px">جارٍ فتح الكاميرا…</p>`,
      onOpen: async f => {
        $('#face-cancel', f).addEventListener('click', () => fin({ ok: false, reason: 'cancel' }));
        const v = $('#cam', f); const st = $('#face-status', f);
        try { await openCamera(v); } catch (e) { fin({ ok: false, reason: 'camera' }); return; }
        const ok = await loadFaceApi(m => { if (st) st.textContent = m; }); if (!ok) { fin({ ok: false, reason: 'load' }); return; }
        if (st) st.textContent = 'جارٍ التحقق…'; const th = Math.min(0.6, (+faceCfg().threshold || 0.5) + 0.05); const t0 = Date.now(); let best = 9;
        const loop = async () => {
          if (done) return; if (!$('#cam')) { fin({ ok: false, reason: 'cancel' }); return; }
          try { const r = await faceDescriptor(v); const ov = $('#camov'); if (!r) { if (ov) ov.innerHTML = ''; if (st) st.textContent = 'لا يوجد وجه أمام الكاميرا — اقترب قليلًا'; } else { if (ov) ov.innerHTML = `<i style="left:${r.box.x / v.videoWidth * 100}%;top:${r.box.y / v.videoHeight * 100}%;width:${r.box.width / v.videoWidth * 100}%;height:${r.box.height / v.videoHeight * 100}%"></i>`; const dist = Math.min(...w.face.d.map(d => faceDistance(r.d, d))); best = Math.min(best, dist); if (dist <= th) { fin({ ok: true, dist: r2(dist) }); return; } if (st) st.textContent = 'جارٍ التحقق… ثبّت الموبايل أمام وجهك'; } } catch (e) { console.warn(e); }
          if (Date.now() - t0 > (opts.timeout || 20000)) { fin({ ok: false, reason: 'nomatch', dist: r2(best) }); return; }
          setTimeout(loop, 400);
        };
        loop();
      } });
  });
}
/* override: self punch = device biometric (if set) + face selfie (if set) + location (in punchGeo) */
