REQ_TYPES.punch = 'نسيان بصمة';
const PUNCH_KINDS = { in: 'حضور', out: 'انصراف', both: 'حضور وانصراف' };
const CHAIN_ROLES = ['head', 'manager', 'acc', 'hr', 'admin'];
const CHAIN_LABEL = { head: 'رئيس القسم', manager: 'مدير المصنع', acc: 'مسؤول الحسابات', hr: 'مدير الحسابات والموارد البشرية', admin: 'المالك (رئيس مجلس الإدارة)', employee: 'الموظف', office: 'المكتب', purch: 'مسؤول المشتريات', fleet: 'مدير الحركة' };
const DEFAULT_CHAINS = { leave: ['head', 'hr'], leaveThuSat: ['head', 'manager'], permission: ['head', 'hr'], advance: ['head', 'manager', 'hr'], punch: ['head', 'manager', 'hr'], password: ['hr'], estimate: ['acc', 'hr', 'admin'], trip: ['manager'], purchase_exception: ['manager'], penalty_cancel: ['head', 'hr', 'admin'] };
const chainFor = type => { const c = S.settings.policy?.chains?.[type]; const v = Array.isArray(c) ? c.filter(x => CHAIN_ROLES.includes(x)) : null; return v && v.length ? v : (DEFAULT_CHAINS[type] || ['hr']); };
const escalateHours = () => { const h = +S.settings.policy?.escalateHours; return h > 0 ? h : 24; };
const reqChain = r => (Array.isArray(r.chain) && r.chain.length) ? r.chain : chainFor(r.type);
