  const st = reqStage(r); if (!stepActor(st.role, r)) { toast(`الطلب الآن عند ${CHAIN_LABEL[st.role]} — الدور ليس لك في الاعتماد`, 'err'); return false; }
  const me = S.session || {}; const now = nowISO(); const approvals = (r.approvals || []).slice(); const thread = (r.thread || []).slice();
