/* ---------------- viewer shell ---------------- */
let _viewer = null;
function viewerClose() { if (!_viewer) return; try { _viewer.dispose && _viewer.dispose(); } catch (e) { /* ignore */ } const el = $('#nfviewer'); if (el) el.remove(); document.body.classList.remove('nfv-open'); _viewer = null; }
