ACTIONS.fileOpen = arg => { const [id, ctx] = (arg || '').split(':'); const f = byId('files', id); if (!f) return; if (f.restricted && typeof canSeeCad === 'function' && !canSeeCad()) { toast('ملف مصدر سرّي — متاح للمكتب الفني والمالك فقط', 'err'); return; } const set = viewerSetFor(f, ctx); openViewer(set, Math.max(0, set.findIndex(x => x.id === id)), { ctx }); };
