      <div class="nfv-title"><b>${esc(f.name)}</b><span class="tiny muted">${esc(FILE_KINDS[f.kind]?.[0] || '')}${f.rev ? ' · ' + esc(f.rev) : ''}${ctxLabel ? ' · ' + esc(ctxLabel) : ''}${f.note ? ' · ' + esc(f.note) : ''}</span></div>
