/* ---------------- boot / session ---------------- */
async function sbBoot() {
  const c = nfConfig(); if (!window.supabase || !window.supabase.createClient) { try { await vendorLoad('supabase'); } catch (e) { toast('تعذّر تحميل مكتبة قاعدة البيانات', 'err'); return false; } }
  S.sb = window.supabase.createClient(c.supabaseUrl, c.supabaseAnonKey, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: false } });
  S.mode = 'sb'; S.db = sbBackend(S.sb); S.canWrite = true;
  sbHealInvoke(S.sb);
  try { const { data } = await S.sb.auth.getSession(); S.sbUser = data && data.session ? data.session.user : null; } catch (e) { S.sbUser = null; }
  try { const { data } = await S.sb.rpc('nf_needs_bootstrap'); S.sbBootstrap = data === true; } catch (e) { S.sbBootstrap = false; }
  S.sb.auth.onAuthStateChange((ev, session) => { if (ev === 'SIGNED_OUT') { S.sbUser = null; } else if (session) S.sbUser = session.user; if (ev === 'TOKEN_REFRESHED' || ev === 'SIGNED_IN') { /* nothing */ } });
  if (S.sbUser) { sbStartData(); } else { S.staffReady = true; }
  return true;
}
