/* ---------------- files on Supabase Storage ---------------- */
(() => {
  const put0 = Files.put.bind(Files), url0 = Files.url.bind(Files), blob0 = Files.blob.bind(Files), remove0 = Files.remove.bind(Files), can0 = Files.canUpload.bind(Files), hint0 = Files.uploadHint.bind(Files);
  const _signed = new Map();
  Files.canUpload = () => sbOn() ? writable() : can0();
  Files.uploadHint = () => sbOn() ? '' : hint0();
  Files.put = async (blob, mime) => {
    if (!sbOn()) return put0(blob, mime);
    const key = `${todayISO().slice(0, 7)}/${uid()}`; const { error } = await S.sb.storage.from('files').upload(key, blob, { contentType: mime || blob.type || 'application/octet-stream', upsert: false });
    if (error) { const e = new Error(error.message || 'upload'); e.code = /size|large/i.test(error.message || '') ? 'too_large' : /policy|security|denied|unauthorized/i.test(error.message || '') ? 'not_granted' : 'upstream_error'; throw e; }
    return { store: 'sb', ref: key, enc: null, mime: mime || blob.type, size: blob.size };
  };
  Files.url = async f => {
    if (!f || f.store !== 'sb') return url0(f);
    const c = _signed.get(f.ref); if (c && c.exp > Date.now()) return c.url;
    const { data, error } = await S.sb.storage.from('files').createSignedUrl(f.ref, 3600); if (error || !data) return null; _signed.set(f.ref, { url: data.signedUrl, exp: Date.now() + 50 * 60 * 1000 }); return data.signedUrl;
  };
  Files.blob = async f => { if (!f || f.store !== 'sb') return blob0(f); const { data, error } = await S.sb.storage.from('files').download(f.ref); if (error) throw new Error(error.message || 'download'); return data; };
  Files.remove = async f => { if (!f || f.store !== 'sb') return remove0(f); try { await S.sb.storage.from('files').remove([f.ref]); } catch (e) { console.warn(e); } };
})();

/* ---------------- backup: export / import (all modes) ---------------- */
