/* ---------------- installable app: service worker + update notice ---------------- */
function pwaInit() {
  if (!('serviceWorker' in navigator) || (window.claude && typeof window.claude.use === 'function') || !/^https?:$/.test(location.protocol) || !window.NF_PWA) return;
  navigator.serviceWorker.register('sw.js', { updateViaCache: 'none' }).then(reg => {
    const notify = () => { const t = $('#toasts'); if (!t) return; if ($('#nf-update')) return; const el = document.createElement('div'); el.id = 'nf-update'; el.className = 'toast'; el.style.pointerEvents = 'auto'; el.style.cursor = 'pointer'; el.textContent = 'يوجد تحديث للتطبيق — اضغط هنا للتحديث (بياناتك محفوظة على السيرفر)'; el.onclick = () => { if (reg.waiting) reg.waiting.postMessage('skipWaiting'); }; t.appendChild(el); };
    if (reg.waiting && navigator.serviceWorker.controller) notify();
    reg.addEventListener('updatefound', () => { const nw = reg.installing; if (!nw) return; nw.addEventListener('statechange', () => { if (nw.state === 'installed' && navigator.serviceWorker.controller) notify(); }); });
    setInterval(() => reg.update().catch(() => { }), 60 * 60 * 1000);
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') reg.update().catch(() => { }); });
  }).catch(e => console.warn('sw', e));
  let reloading = false; navigator.serviceWorker.addEventListener('controllerchange', () => { if (reloading) return; reloading = true; location.reload(); });
}
