  if (r.type === 'purchase_exception') { const p = r.purchaseId ? byId('purchases', r.purchaseId) : null; if (p) await Store.update('purchases', p.id, { exception: { status: 'approved', at: nowISO(), byName: S.session?.name || '' } }); return; }
