  if (next === 'production') { await notifyRole('manager', `${cur.code} جاهز للتشغيل — الخامات وصلت`, cur.title, { orderId: cur.id, id: `mgr_flow_${cur.id}` }); if (orderReleased(cur)) await notifyOrderDrawings(cur, 'اكتملت المقاسات والرسومات والخامات — ابدأ التشغيل'); }
