/* ---------------- product stages & catalogue colours (LOF pipeline) ---------------- */
const PRODUCT_STAGES = { proposal: ['مقترح — بعد عرض السعر', 'warn'], coded: ['مكوّد — بانتظار رسومات التصنيع', 'acc'], ready: ['رسومات جاهزة', 'good'] };
const productStage = p => p.stage || (filesOf('product', p.id).some(f => f.kind === 'drawing') ? 'ready' : 'coded');
