ACTIONS.productStage = async arg => { const [id, st] = arg.split(':'); const p = byId('products', id); if (!p || !seesProducts() || !PRODUCT_STAGES[st]) return; await Store.update('products', id, { stage: st, stageAt: nowISO(), stageBy: S.session?.name || '' }); toast(`المنتج الآن: ${PRODUCT_STAGES[st][0]}`); };
function productPipelineCard(p) {
  const st = productStage(p); const cols = productColors(p); const q = p.quotationId ? byId('quotations', p.quotationId) : null;
  return `<div class="card"><div class="cardhead"><h3>مسار المنتج</h3><div class="grow"></div>${productStageBadge(p)}</div>
    <div class="rsteps">${Object.entries(PRODUCT_STAGES).map(([k, v], i) => { const idx = Object.keys(PRODUCT_STAGES).indexOf(st); return `<div class="rstep ${i < idx ? 'good' : i === idx ? 'warn' : ''}"><div class="rn">${i + 1}</div><div><div class="small bold">${esc(v[0].split(' — ')[0])}</div></div></div>`; }).join('<div class="rarrow">←</div>')}</div>
    <div class="grid g2" style="gap:8px 14px;font-size:13px;margin-top:10px"><div><div class="tiny muted">كود الكتالوج</div><span class="code">${esc(p.catalogCode || p.code || '—')}</span></div><div><div class="tiny muted">عرض السعر الأصلي</div>${q ? `<a href="#/quotes/${q.id}">${esc(q.number)}</a>` : '<span class="muted">—</span>'}</div><div style="grid-column:1/-1"><div class="tiny muted">ألوان / تشطيبات الكتالوج</div>${cols.length ? cols.map(c => `<span class="badge">${esc(c)}</span>`).join(' ') : '<span class="muted">لم تُحدَّد بعد</span>'}</div></div>
    ${seesProducts() && writable() ? `<div class="row no-print" style="margin-top:10px;gap:6px">${st !== 'coded' ? `<button class="btn xs" data-action="productStage" data-arg="${p.id}:coded">تعليم: مكوّد</button>` : ''}${st !== 'ready' ? `<button class="btn xs p" data-action="productStage" data-arg="${p.id}:ready">${icon('check')}رسومات التصنيع جاهزة</button>` : ''}${st !== 'proposal' ? `<button class="btn xs ghost" data-action="productStage" data-arg="${p.id}:proposal">إرجاع لمقترح</button>` : ''}</div>` : ''}
    <div class="tiny muted" style="margin-top:8px">المنتج الجديد للمشاريع الكبيرة: عرض سعر أولًا ← موافقة العميل ← تكويد وإدخال الكتالوج ← رسومات التصنيع من المكتب الفني ← أمر التشغيل.</div>
  </div>`;
}
/* product form extras (part 25 form is extended by re-rendering these fields into the modal) */
