const _productNew0 = ACTIONS.productNew, _productEdit0 = ACTIONS.productEdit;
function injectProductExtras(p) { const f = $('#mform'); if (!f) return; const anchor = $('#f-desc', f)?.closest('.field'); if (!anchor || $('#f-colors', f)) return; anchor.insertAdjacentHTML('beforebegin', productExtraFields(p)); }
