const proofRequired = () => (S.settings.policy || {}).proofRequired !== false;
async function fileToThumb(file, max = 520) {
  try {
    const mime = (file.type || '').toLowerCase();
    if (mime.startsWith('image/') && mime !== 'image/svg+xml') return await imageThumb(URL.createObjectURL(file), max);
    if (mime === 'application/pdf') return (await pdfThumb(file)).thumb;
  } catch (e) { console.warn('thumb', e); }
  return null;
}
/* store a proof file: on the file store when possible, otherwise a thumbnail-only record (demo / read-only modes) */
async function proofAttach(file, meta) {
  if (Files.canUpload()) { try { return await attachFile(file, meta); } catch (e) { console.warn('upload', e); } }
  const thumb = await fileToThumb(file, 640);
  const doc = { id: uid(), name: file.name, kind: meta.kind || 'proof', mime: fileMimeOf(file), size: file.size, note: meta.note || '', ownerKind: meta.ownerKind, ownerId: meta.ownerId, productId: null, orderId: null, byName: S.session?.name || '', thumb, pages: null, store: 'thumb', ref: null };
  await Store.save('files', doc, { silent: true }); return doc;
}
/* thumbnail-only files open in a lightbox instead of the viewer */
const _fileOpenProof0 = ACTIONS.fileOpen;
ACTIONS.fileOpen = arg => { const [id] = (arg || '').split(':'); const f = byId('files', id); if (f && f.store === 'thumb') { lightbox(f.thumb, `${f.name}${f.note ? ' — ' + f.note : ''}`); return; } _fileOpenProof0(arg); };
function lightbox(src, caption) {
  if (!src) { toast('لا توجد صورة محفوظة لهذا الإثبات', 'err'); return; }
  const el = document.createElement('div'); el.className = 'lightbox'; el.innerHTML = `<img src="${esc(src)}" alt="">${caption ? `<div class="cap">${esc(caption)}</div>` : ''}`; el.addEventListener('click', () => el.remove()); document.body.appendChild(el);
}
ACTIONS.lightbox = arg => { const [kind, id, key] = (arg || '').split(':'); let pr = null; if (kind === 'task') pr = byId('tasks', id)?.proof; else if (kind === 'stage') pr = ((byId('orders', id) || {}).stages || {})[key]?.proof; else if (kind === 'hand') pr = ((byId('orders', id) || {}).handovers || {})[key]; else if (kind === 'deliv') pr = (byId('orders', id) || {}).deliveryProof; else if (kind === 'ext') pr = (byId('extorders', id) || {})[key]; else if (kind === 'trip') pr = (byId('trips', id) || {})[key]; if (pr && pr.fileIds && pr.fileIds.length && byId('files', pr.fileIds[0]) && byId('files', pr.fileIds[0]).store !== 'thumb') { ACTIONS.fileOpen(pr.fileIds[0] + ':att'); return; } lightbox(pr && pr.thumb, pr ? `${pr.byName || ''} · ${fmtDate((pr.at || '').slice(0, 10))}${pr.note ? ' — ' + pr.note : ''}` : ''); };

/* ---------------- the proof dialog ----------------
   resolves { fileIds, thumb, note, status, at, by, byName } — or null when cancelled */
function proofDialog(opts) {
  return new Promise(resolve => {
    let settled = false; const done = v => { if (settled) return; settled = true; clearInterval(iv); resolve(v); };
    const canUp = Files.canUpload(); const st = opts.status || null;
    openModal({ title: opts.title, submitLabel: opts.submitLabel || 'تسجيل وتوثيق', body: `<div class="form">
      ${opts.intro ? `<div class="banner info full" style="margin:0">${icon('info')}<span>${esc(opts.intro)}</span></div>` : ''}
      ${st ? `<div class="field full"><label>${esc(opts.statusLabel || 'الحالة')}</label><div class="seg" id="pf-status">${st.map((s, i) => `<button type="button" class="${i === 0 ? 'on' : ''}" data-st="${esc(s[0])}">${esc(s[1])}</button>`).join('')}</div><input type="hidden" name="status" value="${esc(st[0][0])}"></div>` : ''}
      <div class="field full"><label>${esc(opts.fileLabel || 'صورة / ملف الإثبات')}${opts.requireFile === false ? ' (اختياري)' : ''}${opts.fileOptionalWhen ? `<span class="pf-opt" ${st && opts.fileOptionalWhen.includes(st[0][0]) ? '' : 'hidden'}> (اختياري لو في مشكلة)</span>` : ''}</label><label for="pf-file" class="pf-pick">${icon('camera')}<span id="pf-pickt">صوّر أو اختار صورة</span></label><input type="file" id="pf-file" class="pf-in" name="file" accept="image/*,application/pdf" capture="environment" ${opts.multiple ? 'multiple' : ''}><div class="pf-prev" id="pf-prev"></div><div class="tiny muted" style="margin-top:4px">${canUp ? 'تُحفظ على السيستم وتظهر في سجل التوثيق' : 'في هذا الوضع تُحفظ صورة مصغّرة داخل السجل (الرفع الكامل عند التشغيل على السيرفر)'}</div></div>
      ${field(opts.noteLabel || 'تقرير / ملاحظة', `<textarea id="pf-note" name="note" placeholder="${esc(opts.notePlaceholder || '')}"></textarea>`, 'full')}
    </div>`,
      onOpen: f => { const fi = $('#pf-file', f); if (fi) fi.addEventListener('change', () => { const fs = Array.from(fi.files || []); const pv = $('#pf-prev', f), pt = $('#pf-pickt', f); if (pt) pt.textContent = fs.length ? (fs.length > 1 ? `✓ ${fs.length} صور — غيّرهم` : '✓ الصورة جاهزة — غيّرها') : 'صوّر أو اختار صورة'; if (pv) { pv.innerHTML = ''; fs.slice(0, 4).forEach(x => { if (/^image\//.test(x.type || '')) { const im = document.createElement('img'); im.src = URL.createObjectURL(x); im.alt = ''; pv.appendChild(im); } else { const d = document.createElement('span'); d.className = 'pf-doc'; d.textContent = '📄 ' + (x.name || 'ملف'); pv.appendChild(d); } }); } $('.pf-pick', f)?.classList.toggle('on', !!fs.length); });
        const seg = $('#pf-status', f); if (seg) seg.addEventListener('click', ev => { const b = ev.target.closest('[data-st]'); if (!b) return; ev.preventDefault(); $$('button', seg).forEach(x => x.classList.toggle('on', x === b)); $('[name=status]', f).value = b.dataset.st; const po = $('.pf-opt', f); if (po && opts.fileOptionalWhen) po.hidden = !opts.fileOptionalWhen.includes(b.dataset.st); }); },
      onSubmit: async f => {
        const d = formData(f); const files = Array.from($('#pf-file', f)?.files || []);
        if (opts.requireFile !== false && !(opts.fileOptionalWhen || []).includes(d.status) && !files.length) { toast('الصورة أو الملف مطلوب للتوثيق', 'err'); return false; }   /* v7.26: fileOptionalWhen — e.g. a trip that ended with a problem (nothing to photograph) */
        if (opts.requireNote && !(d.note || '').trim()) { toast('اكتب التقرير / الملاحظة', 'err'); return false; }
        const res = { note: (d.note || '').trim(), status: d.status || null, fileIds: [], thumb: null, at: nowISO(), by: S.session?.id || null, byName: S.session?.name || '' };
        for (const file of files) { const doc = await proofAttach(file, { kind: opts.kind || 'proof', ownerKind: opts.ownerKind || 'proof', ownerId: opts.ownerId || '', note: res.note }); if (doc) { res.fileIds.push(doc.id); if (!res.thumb && doc.thumb) res.thumb = doc.thumb; } }
        if (!res.thumb && files.length) res.thumb = await fileToThumb(files[0]);
        done(res); return true;
      } });
    const iv = setInterval(() => { if (!document.getElementById('mform')) done(null); }, 300);
  });
}
const proofChip = (pr, arg, label) => pr ? `<button type="button" class="pchip" data-action="lightbox" data-arg="${esc(arg)}" title="${esc(pr.note || '')}">${pr.thumb ? `<img src="${esc(pr.thumb)}" alt="">` : icon('check')}<span class="t">${esc(label || 'موثّق')} · ${esc(pr.byName || '')} ${fmtDate((pr.at || '').slice(0, 10))}${pr.note ? ` — ${esc(pr.note)}` : ''}</span></button>` : '';
