/* ---------------- stages: finish with a photo, next department receives with a report ---------------- */
function prevDoneDept(o, deptId) { const route = o.route || []; const i = route.indexOf(deptId); for (let j = i - 1; j >= 0; j--) { const s = (o.stages || {})[route[j]]; if (s && s.status === 'done') return route[j]; if (s && s.status === 'skipped') continue; return null; } return null; }
