  if (!pr) return false;
  await Store.update('orders', o.id, { handovers: { [deptId]: Object.assign({ from }, pr) } });
  const ht = byId('tasks', `hnd_${o.id}_${deptId}`); if (ht && ht.status !== 'done') await Store.update('tasks', ht.id, { status: 'done', doneAt: nowISO(), doneByName: S.session?.name || '', proof: pr });
  if (pr.status === 'issue') {
    await notifyRole('manager', `مشكلة في استلام ${o.code} بين ${deptName(from)} و${deptName(deptId)}`, `${pr.note}\nسجّلها ${pr.byName} — راجع سجل التوثيق داخل الأمر.`, { orderId: o.id, priority: 'urgent', id: `hnd_issue_${o.id}_${deptId}` });
    await Store.save('tasks', { id: `hnd_back_${o.id}_${deptId}_${Date.now().toString(36)}`, title: `ملاحظة استلام على شغل قسمك — ${o.code}`, desc: `${deptName(deptId)} استلم الشغل وسجّل مشكلة: ${pr.note}`, deptId: from, assigneeId: null, orderId: o.id, dueDate: todayISO(), priority: 'urgent', status: 'open', kind: 'task', source: 'handover', createdBy: S.session?.id || null, createdByName: S.session?.name || '', createdAt: nowISO(), updatedAt: nowISO() }, { silent: true });
    toast('تم تسجيل الاستلام مع مشكلة — وصل إخطار لمدير المصنع والقسم المسلّم', 'err');
  } else toast('تم توثيق الاستلام');
