  return `<div class="card"><div class="cardhead"><h3>التشغيل الخارجي (مصانع خدمية)</h3><span class="muted small">${arr.length}</span><div class="grow"></div>${canExt() && isOpen(o) ? `<button class="btn sm" data-action="extNew" data-arg="${o.id}">${icon('plus')}أمر خارجي</button>` : ''}</div>${arr.length ? `<div class="list">${arr.map(extItem).join('')}</div>` : '<div class="muted small">لا يوجد شغل خارجي لهذا الأمر</div>'}</div>`;
