  const foot = document.querySelector('.side .foot'); if (foot && !document.querySelector('.side [data-action=demoSwitch]') && (isAdmin() || S.demoOrig)) foot.insertAdjacentHTML('beforebegin', `<div style="padding:6px 12px"><button class="btn sm" style="width:100%" data-action="demoSwitch">🎭 جرّب السيستم بدور آخر</button></div>`);
  const top = document.getElementById('topbar'); if (top && S.demoOrig && !top.querySelector('[data-action=demoBack]')) top.insertAdjacentHTML('afterbegin', `<button class="btn xs p" data-action="demoBack" style="margin-inline-end:8px">↩ رجوع للمالك</button>`);
