const GPS_BRIDGE_DEFAULT = { url: 'https://erhcnkjyaumdoixkksbz.supabase.co/functions/v1/gps-bridge', key: '__NF_GPS_KEY__', platform: 'eTrack (api.etrack.vip)' };
