  const headers = {}; if (gpsAuthed()) { try { const { data } = await S.sb.auth.getSession(); if (data && data.session) { headers.Authorization = 'Bearer ' + data.session.access_token; if (window.NF_CONFIG && window.NF_CONFIG.supabaseAnonKey) headers.apikey = window.NF_CONFIG.supabaseAnonKey; } } catch (e) { /* fall back to the key */ } }
