function officeZone() { const g = officeCfg(); return (g.lat != null && g.lat !== '' && g.lng != null && g.lng !== '') ? { id: 'office', name: 'المكتب', lat: +g.lat, lng: +g.lng, radius: +g.radius || 150 } : null; }
