  const fz = factoryZone(); const oz = officeZone(); const manual = activeSitesFor(w, date).map(s => ({ id: s.id, name: s.name, lat: +s.lat, lng: +s.lng, radius: +s.radius || 50, to: s.to })); const proj = projectZones(w, date);
