  try { await vendorLoad('leaflet'); } catch (e) { const off = $('.mp-off', box); if (off) off.textContent = 'تعذّر تحميل مكتبة الخريطة — استخدم «موقعي الآن» أو الصق رابط Google Maps'; return; }
  const L = window.L; const off = $('.mp-off', box); if (off) off.remove();
