  fleet: [{ name: 'مشاوير في موعدها', unit: '%', target: 95, dir: 'up' }, { name: 'صيانة دورية في موعدها', unit: '%', target: 100, dir: 'up' }],
  driver: [{ name: 'تطابق مسار الهاتف مع GPS العربية', unit: '%', target: 85, dir: 'up' }, { name: 'استهلاك وقود (لتر/100كم) مقابل معيار العربية', unit: '%', target: 100, dir: 'down' }],
  manager: [{ name: 'أوامر مسلَّمة في موعدها', unit: '%', target: 85, dir: 'up' }, { name: 'طلبات معلقة أكثر من 24 ساعة', unit: 'عدد', target: 0, dir: 'down' }],
