function vBoards() { const html = vBoardsBase(); if (!aiDeptScoped() || !canSee('ai')) return html; return `<div class="card" style="margin-bottom:12px"><div class="row" style="gap:12px;flex-wrap:wrap"><div class="row" style="gap:10px"><span class="avatar" style="background:var(--accent-soft);color:var(--accent)">${icon('star')}</span><div><div class="bold">مساعد القسم</div><div class="small muted">اسأله: مين متأخر؟ إيه أولويات النهارده؟ وينفّذ لك مهام داخل قسمك</div></div></div><div class="grow"></div><a class="btn sm p" href="#/ai">${icon('star')}افتح المساعد</a></div></div>` + html; }
function viewTitleDeptAi() { const t = viewTitleBase(); if (S.route.view === 'ai') { t.title = aiTitle(); if (aiDeptScoped()) t.sub = 'متابعة مهام قسمك وأوامره وعمالك — بلا أرقام مالية'; else if (['manager', 'vice'].includes(role())) t.sub = 'مراجعة التشغيل والمخاطر واقتراح الإجراءات — بلا أرقام مالية'; } return t; }
/* =====================================================================
   v4.5 — شرح البرنامج لكل موظف حسب دوره: مكتبة فيديوهات (رابط يوتيوب/درايف/
   ملف mp4) تُدار من الإعدادات وتظهر تلقائيًا في «بوابتي» وفي كل صفحة
   (زر «إزاي أستخدم الصفحة دي؟») + دليل مكتوب خطوة بخطوة لكل دور وصفحة
   ===================================================================== */
const helpCfg = () => Object.assign({ videos: [] }, S.settings.help || {});
const helpVideos = () => helpCfg().videos || [];
const videoForMe = v => !v.roles || !v.roles.length || v.roles.includes(role()) || (v.roles.includes('employee') && !!S.session?.workerId);
const helpVideosFor = (view) => helpVideos().filter(v => videoForMe(v) && (!view || !v.views || !v.views.length || v.views.includes(view)));
function videoEmbed(v) {
  const u = String(v.url || '').trim();
  let m = /(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|shorts\/|embed\/))([\w-]{6,})/.exec(u); if (m) return `<div class="vidwrap"><iframe src="https://www.youtube.com/embed/${m[1]}?rel=0" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen loading="lazy"></iframe></div>`;
  m = /drive\.google\.com\/file\/d\/([\w-]+)/.exec(u); if (m) return `<div class="vidwrap"><iframe src="https://drive.google.com/file/d/${m[1]}/preview" allow="autoplay" allowfullscreen loading="lazy"></iframe></div>`;
  if (/\.(mp4|webm|mov|m4v)(\?|$)/i.test(u)) return `<div class="vidwrap"><video src="${esc(u)}" controls playsinline preload="metadata"></video></div>`;
  if (v.fileId && byId('files', v.fileId)) return `<button class="btn p" data-action="fileOpen" data-arg="${v.fileId}:att">${icon('play')}تشغيل الفيديو المرفوع</button>`;
  return u ? `<a class="btn" href="${esc(u)}" target="_blank" rel="noopener">${icon('link')}فتح الفيديو</a>` : '<div class="muted small">لا يوجد رابط</div>';
}
