const roleGuide = () => ROLE_GUIDES[role()] || (S.session?.workerId ? ROLE_GUIDES.employee : null);
/* ---------------- topbar button + modal ---------------- */
function helpBtnHTML() { if (!S.session || role() === 'kiosk') return ''; const n = helpVideosFor(S.route.view).length; return `<button class="helpbtn" data-action="helpOpen" title="إزاي أستخدم الصفحة دي؟">${icon('play')}<span>إزاي أستخدم الصفحة دي؟</span>${n ? `<b class="num">${n}</b>` : ''}</button>`; }
function helpModalBody(view, roleOnly) {
  const vids = roleOnly ? helpVideosFor(null) : helpVideosFor(view); const pg = !roleOnly && PAGE_GUIDES[view]; const rg = roleGuide();
  const vhtml = vids.length ? `<div class="stack" style="gap:14px">${vids.map(v => `<div><div class="bold" style="margin-bottom:6px">${icon('play')} ${esc(v.title)}</div>${videoEmbed(v)}${v.desc ? `<div class="small muted" style="margin-top:6px">${esc(v.desc)}</div>` : ''}</div>`).join('')}</div>` : `<div class="banner info" style="margin:0">${icon('info')}<span>لا يوجد فيديو مرفوع ${roleOnly ? 'لدورك' : 'لهذه الصفحة'} بعد${isAdmin() ? ' — ارفعه من الإعدادات ← شرح البرنامج' : ''}. الدليل المكتوب أدناه يشرح الخطوات.</span></div>`;
  return `${vhtml}${pg ? `<div class="guide" style="margin-top:14px"><h4>${esc(VIEW_TITLES[view] || '')} — الخطوات</h4><ol>${pg.map(s => `<li>${esc(s)}</li>`).join('')}</ol></div>` : ''}${rg ? `<div class="guide" style="margin-top:14px;border-top:1px solid var(--line);padding-top:10px"><h4>${esc(rg.title)}</h4><ol>${rg.steps.map(s => `<li>${esc(s)}</li>`).join('')}</ol></div>` : ''}`;
}
