/* ---------------- fleet: trip for a purchase order ---------------- */
function tripForm(t) { const html = tripFormBase(t); return html.replace('<div class="form">', `<div class="form"><input type="hidden" name="purchaseId" value="${esc(t.purchaseId || '')}">`); }
async function saveTrip(f, t) { const d = formData(f); const r = await saveTripBase(f, t); const tr = list('trips').find(x => x.number === (d.number || '')); if (tr && d.purchaseId && tr.purchaseId !== d.purchaseId) await Store.update('trips', tr.id, { purchaseId: d.purchaseId }); return r; }
