const DEFAULT_MAINT = [{ type: 'oil', everyKm: 5000, everyDays: 0 }, { type: 'tires', everyKm: 40000, everyDays: 0 }, { type: 'brakes', everyKm: 20000, everyDays: 0 }, { type: 'service', everyKm: 10000, everyDays: 180 }, { type: 'license', everyKm: 0, everyDays: 365 }];
