function jobHolders(j) { const ws = list('workers').filter(w => w.status !== 'inactive' && (w.jobId === j.id || (!w.jobId && w.role === j.role && (j.trade ? w.trade === j.trade : !['employee', 'none'].includes(j.role))))); const st = !j.trade && !['employee', 'none', 'head'].includes(j.role) ? list('staff').filter(s => s.active !== false && s.role === j.role && s.id !== 'local-admin').map(s => ({ id: s.id, name: s.name, staff: true, deptId: (s.deptIds || [])[0] })) : []; return ws.concat(st); }
