  const set = (sel, v) => { const el = $(sel, f); if (el && v) { el.value = v; el.dispatchEvent(new Event('change', { bubbles: true })); } };
  set('#f-trade', o.dataset.trade); if (!['prod', 'inst'].includes(o.dataset.dept)) set('#f-deptId', o.dataset.dept);
  const rs = $('#f-role', f); if (rs && o.dataset.role && [...rs.options].some(x => x.value === o.dataset.role)) set('#f-role', o.dataset.role);
