  const btns = `<a class="iconbtn camicon" href="#/tasks/${t.id}" title="صفحة المهمة والمحادثة">${icon('chat')}${u ? `<span class="n">${u}</span>` : th ? `<span class="n" style="background:var(--muted)">${th}</span>` : ''}</a>${writable() && taskVisible(t) ? `<button class="iconbtn camicon" data-action="taskPhoto" data-arg="${t.id}" title="تصوير / رفع صورة توثيق">${icon('camera')}${n ? `<span class="n">${n}</span>` : ''}</button>` : ''}`;
  html = html.replace('<div class="end"><div class="row" style="gap:4px;flex-wrap:wrap;justify-content:flex-end">', '<div class="end"><div class="row" style="gap:4px;flex-wrap:wrap;justify-content:flex-end">' + btns);
