  const tilesHTML = list => `<div class="tgal big">${list.map(p => `<div class="ph" data-action="taskPhotoOpen" data-arg="${t.id}:${p.id}">${photoSrc(p) ? `<img src="${esc(photoSrc(p))}" alt="">` : ''}<div class="who">${esc(p.byName || '')} · ${fmtDate((p.at || '').slice(0, 10))}</div>${isAdmin() || p.by === S.session?.id ? `<button class="iconbtn" style="position:absolute;top:2px;left:2px;background:rgba(0,0,0,.5);color:#fff" data-action="taskPhotoDel" data-arg="${t.id}:${p.id}">${icon('x')}</button>` : ''}</div>`).join('')}</div>`;
