ACTIONS.pjStage = arg => { const f = S.ui.filter.pjdetail ||= {}; f.stage = f.stage === arg ? '' : arg; render(false); };
ACTIONS.pjTaskNew = arg => { const [oid, did] = arg.split(':'); if (!canTasks()) return; const t = { orderId: oid, deptId: did }; openModal({ title: 'مهمة جديدة في المرحلة', body: taskForm(t), onSubmit: f => saveTask(f, t) }); };
