  if (col === 'clients') { const ids = new Set(); Array.from(S.data.orders.values()).forEach(o => { if (o.brandId === b) ids.add(o.clientId); }); Array.from(S.data.quotations.values()).forEach(q => { if (q.brandId === b) ids.add(q.clientId); }); return arr.filter(c => c.brandId === b || ids.has(c.id) || c.createdBy === S.session.id); }
