  pickup_ext: [['start', 'انطلاق من المصنع'], ['arrive', 'تم الوصول للمصنع الخدمي'], ['received', 'تم الاستلام'], ['back', 'تم الوصول للمصنع']],
  delivery: [['start', 'انطلاق من المصنع'], ['arrive', 'تم الوصول للعميل'], ['received', 'تم التسليم'], ['back', 'تم الوصول للمصنع']],
  install: [['start', 'انطلاق من المصنع'], ['arrive', 'تم الوصول للموقع'], ['back', 'تم الوصول للمصنع']],
  other: [['start', 'انطلاق'], ['arrive', 'تم الوصول'], ['back', 'تم الرجوع']],
