  const nx = tripNextLeg(t); if (!nx) return;
  if (nx.key === 'start') return ACTIONS.tripStart(id);
  if (nx.key === 'back') return ACTIONS.tripEnd(id);
  if (t.status !== 'started') { toast('ابدأ المشوار أولًا', 'err'); return; }
  const v = byId('vehicles', t.vehicleId); let o = null;
  if (nx.key === 'arrive') { if (v) { o = await odoDialog(`${nx.label} — عداد ${v.name}`, v, 'قراءة العداد عند الوصول (تُحسب منها كيلومترات الضلع)'); if (!o) return; } }
  let pr = null; if (nx.key === 'received') { pr = await proofDialog({ title: nx.label + ` — ${t.number}`, intro: t.kind === 'delivery' ? 'صورة التسليم عند العميل + من استلم' : 'صورة الشغل/الخامات على العربية + العدد والحالة', kind: 'proof', ownerKind: 'trip', ownerId: id, requireNote: true, noteLabel: 'ملاحظة الاستلام', status: [['ok', 'تم بدون مشاكل'], ['issue', 'توجد مشكلة']], statusLabel: 'النتيجة' }); if (!pr) return; }
