  const rec = { key: nx.key, at: nowISO(), pos: p, km: o ? o.km : null, thumb: (o && o.thumb) || (pr && pr.thumb) || null, note: pr ? pr.note : '', status: pr ? pr.status : null };
  const upd = { legs: tripLegs(t).concat([rec]), track: (t.track || []).concat(p ? [p] : []) }; if (nx.key === 'arrive') upd.arrivedAt = rec.at; if (nx.key === 'received') { upd.receivedAt = rec.at; upd.receiveProof = pr; }
