  if (pr && pr.status === 'issue') await notifyRole('fleet', `مشكلة عند ${nx.label} — ${t.number}`, pr.note, { id: `trip_leg_issue_${id}`, priority: 'urgent' });
  if (nx.key === 'received' && t.purchaseId) await notifyRole('purch', `السائق استلم توريد ${byId('purchases', t.purchaseId)?.number || ''}`, `${t.number}: ${pr.note}`, { id: `po_received_${t.purchaseId}`, priority: 'normal' });
