const _tripEndLegs = ACTIONS.tripEnd; ACTIONS.tripEnd = async id => { await _tripEndLegs(id); const t = byId('trips', id); if (t && t.status === 'done' && !tripLegs(t).some(l => l.key === 'back')) await Store.update('trips', id, { legs: tripLegs(t).concat([{ key: 'back', at: t.endedAt || nowISO(), pos: t.endPos || null, km: t.endKm ?? null, thumb: (t.endOdo || {}).thumb || null }]) }, { silent: true }); };
