const riskHref = (o, r) => r.k === 'po' ? '#/purchases' : r.k === 'team' || r.k === 'stage' ? `#/orders/${o.id}` : r.k === 'cash' ? `#/orders/${o.id}` : r.k === 'late' || r.k === 'tight' ? `#/projects/${o.id}` : `#/orders/${o.id}`;
