/* board columns with count / value / weighted */
function crmBoardPro(ls) {
  return `<div class="crm">${crmStageKeys().map(k => { const arr = sortBy(ls.filter(l => l.stage === k), l => l.nextAt || '9'); const v = sum(arr, leadValue); const wv = sum(arr, leadWeighted); return `<div class="col"><div class="ch">${LEAD_STAGES[k][0]}<span class="n">${arr.length}</span><div class="sum"><span>${v ? fmtMoney(v) : '—'}</span>${k !== 'won' && k !== 'lost' && wv ? `<span>مرجّح ${fmtMoney(wv)}</span>` : ''}</div></div><div class="cb">${arr.map(leadCardPro).join('') || '<div class="muted tiny" style="text-align:center;padding:10px">اسحب فرصة هنا من صفحتها</div>'}</div></div>`; }).join('')}</div>`;
}
/* reports: monthly won, funnel, sources donut, cycle */
function crmReportsPro() {
  const ls = leadsAll(); const today = todayISO(); const months = [5, 4, 3, 2, 1, 0].map(i => ymAdd(monthOf(today), -i));
  const won = months.map(m => ({ m, n: ls.filter(l => isWon(l) && (l.wonAt || '').slice(0, 7) === m).length, v: sum(ls.filter(l => isWon(l) && (l.wonAt || '').slice(0, 7) === m), leadValue), c: ls.filter(l => (l.createdAt || '').slice(0, 7) === m).length }));
  const max = Math.max(1, ...won.map(x => x.v)); const maxN = Math.max(1, ...won.map(x => Math.max(x.n, x.c)));
  const stages = crmStageKeys().filter(k => k !== 'lost'); const smax = Math.max(1, ...stages.map(k => ls.filter(l => l.stage === k).length));
  const src = {}; ls.forEach(l => { (src[l.source || 'أخرى'] ||= { n: 0, won: 0, v: 0 }); src[l.source || 'أخرى'].n++; if (isWon(l)) { src[l.source || 'أخرى'].won++; src[l.source || 'أخرى'].v += leadValue(l); } });
  const srcKeys = Object.keys(src); const tot = ls.length || 1; let acc = 0; const cols = ['#1d5fd1', '#0ea5a5', '#7c3aed', '#d97706', '#dc2626', '#059669', '#db2777', '#4b5563'];
  const arcs = srcKeys.map((k, i) => { const p = src[k].n / tot; const a0 = acc * 2 * Math.PI, a1 = (acc + p) * 2 * Math.PI; acc += p; const x0 = 55 + 45 * Math.sin(a0), y0 = 55 - 45 * Math.cos(a0), x1 = 55 + 45 * Math.sin(a1), y1 = 55 - 45 * Math.cos(a1); return `<path d="M${x0} ${y0} A45 45 0 ${p > .5 ? 1 : 0} 1 ${x1} ${y1}" fill="none" stroke="${cols[i % cols.length]}" stroke-width="14"/>`; }).join('');
  const wonLs = ls.filter(l => isWon(l) && l.wonAt && l.createdAt); const cycle = wonLs.length ? Math.round(sum(wonLs, l => daysBetween(l.createdAt.slice(0, 10), l.wonAt.slice(0, 10))) / wonLs.length) : null; const avgDeal = wonLs.length ? Math.round(sum(wonLs, leadValue) / wonLs.length) : null;
  const lost = ls.filter(l => l.stage === 'lost'); const lostR = {}; lost.forEach(l => { lostR[l.lostReason || 'غير محدد'] = (lostR[l.lostReason || 'غير محدد'] || 0) + 1; });
  const acts = {}; ls.forEach(l => (l.activities || []).forEach(a => { if (a.at && a.at >= addDays(today, -30)) acts[a.type] = (acts[a.type] || 0) + 1; }));
  return `<div class="kpis"><div class="kpi good"><div class="v">${fmtMoney(sum(wonLs, leadValue))}</div><div class="l">إجمالي التعاقدات (${wonLs.length})</div></div><div class="kpi"><div class="v">${avgDeal != null ? fmtMoney(avgDeal) : '—'}</div><div class="l">متوسط قيمة التعاقد</div></div><div class="kpi"><div class="v">${cycle != null ? cycle + ' يوم' : '—'}</div><div class="l">متوسط دورة البيع</div></div><div class="kpi"><div class="v">${ls.length ? Math.round(wonLs.length / ls.filter(l => isClosed(l)).length * 100 || 0) : 0}%</div><div class="l">نسبة الفوز (من المغلقة)</div></div></div>
  <div class="grid g2" style="margin-top:12px"><div class="card"><h3>التعاقدات — آخر 6 شهور</h3><div class="crmchart">${won.map(x => `<div class="b" title="${fmtMonth(x.m)}: ${fmtMoney(x.v)} · ${x.n} تعاقد · ${x.c} فرصة جديدة"><b>${x.v ? fmtMoney(x.v / 1000) + 'k' : ''}</b><i class="w" style="height:${Math.max(3, x.v / max * 100)}%"></i><span>${fmtMonth(x.m).slice(0, 6)}</span></div>`).join('')}</div><div class="tiny muted" style="margin-top:6px">فرص جديدة بالشهر: ${won.map(x => x.c).join(' · ')}</div></div>
    <div class="card"><h3>قمع المبيعات</h3><div class="stack" style="gap:6px;margin-top:8px">${stages.map(k => { const n = ls.filter(l => l.stage === k).length; return `<div class="row" style="gap:8px;align-items:center"><span style="width:96px;font-size:12px">${LEAD_STAGES[k][0]}</span><div class="grow" style="height:16px;background:var(--line);border-radius:999px;overflow:hidden"><div style="width:${Math.max(4, n / smax * 100)}%;height:100%;background:${k === 'won' ? 'var(--good)' : 'var(--accent)'};border-radius:999px"></div></div><b style="width:26px;text-align:left">${n}</b></div>`; }).join('')}</div><div class="small" style="margin-top:8px">نسبة التحويل الكلية: <b>${ls.length ? Math.round(wonLs.length / ls.length * 100) : 0}%</b> · خسائر: ${lost.length}${lost.length ? ` (${Object.entries(lostR).map(([k, n]) => `${k} ${n}`).join('، ')})` : ''}</div></div>
    <div class="card"><h3>المصادر</h3><div class="donut" style="margin-top:8px"><svg viewBox="0 0 110 110">${arcs}<text x="55" y="59" text-anchor="middle" font-size="16" font-weight="700" fill="currentColor">${ls.length}</text></svg><div class="lg">${srcKeys.map((k, i) => `<div><i style="background:${cols[i % cols.length]}"></i>${esc(k)}: ${src[k].n}${src[k].won ? ` · ${src[k].won} تعاقد (${fmtMoney(src[k].v)})` : ''}</div>`).join('')}</div></div></div>
    <div class="card"><h3>النشاط — آخر 30 يوم</h3><div class="row" style="gap:10px;flex-wrap:wrap;margin-top:8px">${Object.keys(ACT_TYPES).map(k => `<div class="kpi" style="min-height:auto;padding:10px 12px;flex:1;min-width:90px;text-align:center"><div class="v" style="font-size:20px">${acts[k] || 0}</div><div class="l">${ACT_ICON[k]} ${ACT_TYPES[k]}</div></div>`).join('')}</div><div class="tiny muted" style="margin-top:8px">أنشطة كل الفرص المفتوحة والمغلقة</div></div></div>`;
}
/* follow-ups grouped */
