  const thumb = (label, color) => typeof demoThumb === 'function' ? demoThumb(label, color) : null;
  const wk = id => D.workers.find(x => x.id === id); const DEMO_PW = { salt: 'demo', passHash: '2d1b7b198b4d3a395edd5f1a40de5a0f488b55f1ffa2bb4883e987a48eb9f206' };
