    if (typeof fileIsLink === 'function' && fileIsLink(f)) { await Store.update('files', f.id, { restricted: to }); toast(to ? 'اللينك بقى سرّي — المالك والمكتب الفني بس' : 'اللينك بقى متاح'); render(false); return; }
    if (f.store === 'sb' && f.ref) { const dest = to ? (f.ref.startsWith('cad/') ? f.ref : 'cad/' + f.ref) : f.ref.replace(/^cad\//, ''); if (dest !== f.ref) { const { error } = await S.sb.storage.from('files').move(f.ref, dest); if (error) throw error; await Store.update('files', f.id, { ref: dest, restricted: to, kind: to ? 'cad' : (isCadName(f.name) ? 'other' : f.kind) }); } else await Store.update('files', f.id, { restricted: to }); }
    else await Store.update('files', f.id, { restricted: to, kind: to ? 'cad' : (isCadName(f.name) ? 'other' : f.kind) });
    toast(to ? 'أصبح الملف سرّيًا' : 'أصبح الملف متاحًا'); render(false);
