  if (existing) await Store.update('requests', existing.id, { stepAt: now, thread: (existing.thread || []).concat([{ id: uid(), at: now, by: me.id || null, byName: me.name || '', role: role(), kind: 'system', text: `تحديث المسودة: ${p.stages.length} مراحل · ${p.bom.length} خامات` }]) });
