  fresh.forEach(x => { shown[x.last.id] = Date.now(); }); const ks = Object.keys(shown); if (ks.length > 300) ks.sort((a, b) => shown[a] - shown[b]).slice(0, ks.length - 300).forEach(k => delete shown[k]);
