async function taskPost(t, text, file, opts = {}) {
  const isAudio = file && /^audio\//.test(file.type || '');
  let ok;
  if (isAudio) {
    const m = { id: uid(), at: nowISO(), by: S.session?.id || S.session?.workerId || null, byName: S.session?.name || '', text: (text || '').trim() };
    const doc = await proofAttach(file, { kind: 'chat', ownerKind: 'task', ownerId: t.id }); m.audioFileId = doc.id; m.dur = opts.dur || null;
    const seen = Object.assign({}, t.threadSeen || {}); if (m.by) seen[m.by] = m.at; if (S.session?.workerId) seen[S.session.workerId] = m.at;
    await Store.update('tasks', t.id, { thread: taskThread(t).concat([m]), threadSeen: seen, lastMsgAt: m.at, updatedAt: nowISO() }); ok = true;
  } else ok = await taskPostBase(t, text, file);
  if (ok) { const me = myIds(); const to = Array.from(new Set(taskParties(t).map(p => p.id).filter(id => id && !me.includes(id)))); pushSend(to, `${S.session?.name || 'رسالة'} — ${t.title}`.slice(0, 100), (text || '').trim() || (isAudio ? '🎤 رسالة صوتية' : '📷 صورة'), `/#/tasks/${t.id}`, 'task-' + t.id); }
  return ok;
}
function chatHTMLNotif(t) {
  let h = chatHTMLBase(t); const th = taskThread(t); const me = myIds();
  th.forEach(m => { if (!m.audioFileId) return; const marker = `<div class="by">${esc(m.byName || '')} · ${fmtDate((m.at || '').slice(0, 10))} ${fmtAtTm(m.at)}</div>`; const i = h.indexOf(marker); if (i < 0) return; const j = i + marker.length; h = h.slice(0, j) + `<div class="tx">🎤 رسالة صوتية${m.dur ? ` (${m.dur} ث)` : ''}</div><button class="btn ghost" data-action="voicePlay" data-arg="${esc(m.audioFileId)}">▶ تشغيل</button>` + h.slice(j); });
  if (writable() && taskIsParty(t)) h = h.replace(`<button class="btn ghost" data-action="taskChatPhoto" data-arg="${t.id}" title="صورة">`, `<button class="btn ghost recbtn" id="recbtn" data-action="taskChatVoice" data-arg="${t.id}" title="رسالة صوتية">${icon('mic')}</button><button class="btn ghost" data-action="taskChatPhoto" data-arg="${t.id}" title="صورة">`);
  return h;
}
