/* =====================================================================
   v4.7 — سرّية الأسعار (اتفاق 21 سبتمبر):
   · لا أحد يرى أسعار المنتجات ولا عروض الأسعار ولا الفواتير إلا المالك.
   · مدير الحسابات والموارد البشرية (hr): يطلب «إذن الأسعار» من المالك — يُفتح له لمدة ساعة واحدة.
   · مسؤول الحسابات (acc): لا عروض أسعار ولا فواتير إطلاقًا — عروض أسعار الموردين وأوامر الشراء والمخزن فقط.
   · المدير التجاري / تطوير الأعمال: يرى الأسعار ويفتح أي عرض سعر في أي وقت (بلا إذن).
   · باقي الأدوار (المكتب الفني، الهندسة، الإنتاج، المشتريات، المخازن…): لا عروض ولا فواتير ولا أسعار إطلاقًا.
   · المبالغ داخل ملاحظات أمر التشغيل تُحجب عن غير المصرَّح لهم (شاشة وطباعة).
   ===================================================================== */
(document.body || document.head).insertAdjacentHTML('beforeend', `<style>
.qlock{max-width:560px;margin:30px auto;text-align:center;padding:28px}.qlock .ic{width:56px;height:56px;border-radius:16px;background:var(--warn-soft);color:var(--warn-ink);display:grid;place-items:center;margin:0 auto 12px}.qlock .ic svg{width:26px;height:26px}
.pricebar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}
</style>`);
const PRICE_GRANT_MIN = 60;           // مدير الحسابات / الموارد: ساعة
const QUOTE_GRANT_HOURS = 72;         // المدير التجاري: لكل عرض
const PRICE_ASK_ROLES = ['hr'];            // مدير الحسابات والموارد البشرية فقط يطلب الإذن؛ مسؤول الحسابات (acc) لا يرى العروض/الفواتير إطلاقًا
REQ_TYPES.priceopen = 'إذن الاطلاع على الأسعار (ساعة)'; DEFAULT_CHAINS.priceopen = ['admin'];
REQ_TYPES.quoteopen = 'إذن فتح عرض سعر'; DEFAULT_CHAINS.quoteopen = ['admin'];
const myReqIds = () => { const s = S.session || {}; return [s.workerId, s.id].filter(Boolean); };
const grantAt = r => Date.parse(r.decidedAt || r.stepAt || 0);
function priceGrant() { const me = myReqIds(); if (!me.length) return null; const lim = Date.now() - PRICE_GRANT_MIN * 60 * 1000; return list('requests').find(r => r.type === 'priceopen' && r.status === 'approved' && me.includes(r.requesterId) && grantAt(r) >= lim) || null; }
function pricePending() { const me = myReqIds(); return list('requests').find(r => r.type === 'priceopen' && r.status === 'pending' && me.includes(r.requesterId)) || null; }
const priceAllowed = () => !!S.session && (isAdmin() || role() === 'bdd' || (PRICE_ASK_ROLES.includes(role()) && !!priceGrant()));
const seesPrices = priceAllowed;
/* seesFinance() (02) reads FINANCE_ROLES.includes(role()) — make it follow the grant */
FINANCE_ROLES.splice(0, FINANCE_ROLES.length, 'admin');
FINANCE_ROLES.includes = function (r) { return r === 'admin' || r === 'bdd' || (PRICE_ASK_ROLES.includes(r) && !!priceGrant()); };
/* who may open the quotes / invoices pages at all */
const QUOTE_VIEW_ROLES = ['admin', 'hr', 'bdd'];
/* مسؤول الحسابات: عروض أسعار الموردين وأوامر الشراء والمخزن فقط */
if (Array.isArray(ROLE_VIEWS.acc) && !ROLE_VIEWS.acc.includes('inventory')) ROLE_VIEWS.acc.splice(ROLE_VIEWS.acc.indexOf('purchases'), 0, 'inventory');
Object.keys(ROLE_VIEWS).forEach(r => { if (Array.isArray(ROLE_VIEWS[r]) && !QUOTE_VIEW_ROLES.includes(r)) ROLE_VIEWS[r] = ROLE_VIEWS[r].filter(v => v !== 'quotes' && v !== 'invoices'); });
/* quote-level grant for the commercial director */
function quoteGrant(q) { const me = myReqIds(); if (!me.length) return null; const lim = Date.now() - QUOTE_GRANT_HOURS * 3600 * 1000; return list('requests').find(r => r.type === 'quoteopen' && r.quotationId === q.id && r.status === 'approved' && me.includes(r.requesterId) && grantAt(r) >= lim) || null; }
function quotePending(q) { const me = myReqIds(); return list('requests').find(r => r.type === 'quoteopen' && r.quotationId === q.id && r.status === 'pending' && me.includes(r.requesterId)) || null; }
function quoteAllowed(q) { if (!q || !S.session) return false; if (isAdmin() || role() === 'bdd') return true; if (PRICE_ASK_ROLES.includes(role()) && !!priceGrant()) return true; return false; }
async function sendGrantRequest(type, extra, title, desc) {
  const me = S.session; const w = me.workerId ? byId('workers', me.workerId) : null; const now = nowISO();
  await Store.save('requests', Object.assign({ id: uid(), type, workerId: w ? w.id : null, requesterId: me.workerId || me.id, requesterName: me.name || '', deptId: w ? w.deptId || null : null, reason: '', status: 'pending', chain: chainFor(type), step: 0, stepAt: now, createdBy: me.id || null, createdByName: me.name || '', createdAt: now, from: todayISO(), to: todayISO() }, extra || {}));
  if (typeof notifyOwner === 'function') { try { await notifyOwner(title, desc, { kind: type }); } catch (e) { /* ignore */ } }
  toast('تم إرسال طلب الإذن للمالك'); render(false);
}
ACTIONS.priceAsk = async () => { if (!S.session || !PRICE_ASK_ROLES.includes(role())) return; if (pricePending()) { toast('طلبك بانتظار موافقة المالك'); return; } await sendGrantRequest('priceopen', {}, `طلب إذن أسعار — ${S.session.name || ''}`, `${S.session.name || ''} يطلب الاطلاع على الأسعار وعروض الأسعار لمدة ساعة. اعتمده من الطلبات.`); };
ACTIONS.quoteAsk = async id => { const q = byId('quotations', id); if (!q || !S.session || role() !== 'bdd') return; if (quotePending(q)) { toast('طلبك بانتظار موافقة المالك'); return; } await sendGrantRequest('quoteopen', { quotationId: q.id }, `طلب فتح عرض سعر ${q.number}`, `${S.session.name || ''} يطلب إذن فتح عرض السعر ${q.number} — ${clientName(q.clientId)}.`); };
function reqDescGuard(r) {
  if (r.type === 'quoteopen') { const q = byId('quotations', r.quotationId); return `${r.requesterName || ''} يطلب إذن فتح عرض السعر ${q ? q.number : ''}${q ? ' — ' + clientName(q.clientId) : ''} (صالح ${QUOTE_GRANT_HOURS} ساعة بعد الموافقة)`; }
  if (r.type === 'priceopen') return `${r.requesterName || ''} يطلب الاطلاع على الأسعار وعروض الأسعار والفواتير — يُفتح لمدة ${PRICE_GRANT_MIN} دقيقة بعد الموافقة`;
  return null;
}
function reqDesc(r) { return reqDescGuard(r) || reqDescApr(r); }
/* lock screens */
function lockCard(title, sub, btn) { return `<div class="card qlock"><div class="ic">${icon('alert')}</div><h3>${title}</h3><p class="small ink2" style="margin:8px 0 14px">${sub}</p>${btn}</div>`; }
function priceBar() {
  if (!S.session || !PRICE_ASK_ROLES.includes(role())) return '';
  const g = priceGrant(); if (g) { const left = Math.max(0, Math.round((grantAt(g) + PRICE_GRANT_MIN * 60000 - Date.now()) / 60000)); return `<div class="banner good pricebar">${icon('check')}<span>إذن الأسعار مفتوح — متبقٍ ${left} دقيقة</span></div>`; }
  const p = pricePending(); return `<div class="banner warn pricebar">${icon('alert')}<span>الأسعار وعروض الأسعار مقفولة — تحتاج إذن المالك (يُفتح لمدة ساعة).</span>${p ? '<span class="badge warn">بانتظار الموافقة</span>' : `<button class="btn sm p" data-action="priceAsk">طلب إذن من المالك</button>`}</div>`;
}
const askBtn = () => { const p = pricePending(); return p ? `<span class="badge warn">بانتظار موافقة المالك</span>` : `<button class="btn p" data-action="priceAsk">${icon('check')}طلب إذن من المالك</button>`; };
function vQuoteDetail(id) {
  const q = byId('quotations', id); if (!q) return vQuoteDetailBase(id);
  if (quoteAllowed(q)) return priceBar() + vQuoteDetailBase(id);
  const c = byId('clients', q.clientId);
  if (role() === 'bdd') { const p = quotePending(q); return lockCard(`عرض السعر ${esc(q.number)} — ${esc(c?.name || '')}`, `عروض الأسعار سرّية: تُفتح فقط بإذن من المالك لكل عرض على حدة.${p ? `<br><b>طلبك مُرسَل ${fmtDate((p.createdAt || '').slice(0, 10))} وبانتظار الموافقة.</b>` : ''}`, p ? `<span class="badge warn">بانتظار موافقة المالك</span>` : `<button class="btn p" data-action="quoteAsk" data-arg="${q.id}">${icon('check')}طلب إذن من المالك</button><div class="tiny muted" style="margin-top:12px">بعد الموافقة يُفتح العرض لك لمدة ${QUOTE_GRANT_HOURS} ساعة.</div>`); }
  if (PRICE_ASK_ROLES.includes(role())) return lockCard(`عرض السعر ${esc(q.number)} — ${esc(c?.name || '')}`, 'الأسعار وعروض الأسعار مقفولة — تحتاج إذن المالك (يُفتح لمدة ساعة).', askBtn());
  return lockCard('غير مصرَّح', 'عروض الأسعار سرّية ولا تُعرض لهذا الدور.', '');
}
function vInvoiceDetail(id) {
  const inv = byId('invoices', id); if (!inv) return vInvoiceDetailBase(id);
  if (priceAllowed()) return priceBar() + vInvoiceDetailBase(id);
  const c = byId('clients', inv.clientId);
  if (PRICE_ASK_ROLES.includes(role())) return lockCard(`فاتورة ${esc(inv.number)} — ${esc(c?.name || '')}`, 'الفواتير والأسعار مقفولة — تحتاج إذن المالك (يُفتح لمدة ساعة).', askBtn());
  return lockCard(`فاتورة ${esc(inv.number)}`, 'الفواتير سرّية ولا تُعرض لهذا الدور.', '');
}
