  const todo = ninetyTodo(f);
  return `<div class="blk" style="--c:${NINETY_COS.factory.color}" data-action="ninetyGo" data-arg="factory"><div class="hd"><span class="dot"></span><b>Ninety Fabrication</b><small>· المصنع · حضور ${f.present}/${f.total}</small><span class="open">فتح السيستم ←</span></div>
    <div class="bd"><div class="r">${it(f.appr.length, 'اعتماد مستنيك', 'إجازات · سلف · طلبات', 'wn')}${it(f.transfer.length, 'تحويل لمورد', 'أوامر شراء بانتظارك', 'wn')}${it(f.late.length, 'أوامر متأخرة', 'تجاوزت التسليم', 'bad')}${it(f.open, 'أوامر جارية', 'قيد التشغيل', '')}${it(f.esc.length, 'مهمة مصعَّدة', 'لم يشاهدها المكلَّف', 'bad')}${it(f.suspect.length, 'بصمة مشبوهة', 'تحتاج مراجعة', 'wn')}</div>
    <ul class="todo"><div class="h">مطلوب منك</div>${todo.length ? todo.map(r => `<li data-action="ninetyOpen" data-arg="${esc(r.h)}" data-stop="1"><i style="background:${r.c}"></i>${esc(r.t)}<span class="ar">←</span></li>`).join('') : '<li><i style="background:#4f8a6d"></i>مفيش حاجة مستنياك دلوقتي ✓</li>'}</ul></div></div>`;
