  const rows = []; const row = x => `<a class="item" href="#/purchases/${x.id}"><div class="main"><div class="title"><span class="code">${esc(x.number)}</span> ${x.kind === 'rfq' ? 'طلب عرض سعر — أصناف جديدة' : 'طلب شراء الخامات'}</div><div class="meta"><span>${(x.kind === 'rfq' ? x.rfqItems || [] : x.needItems || []).slice(0, 4).map(i => esc(i.name || '')).join('، ')}</span></div></div><div class="end">${badge(PO_STATUS, x.status)}</div></a>`;
  if (p.fromNeed && byId('purchases', p.fromNeed)) rows.push(row(byId('purchases', p.fromNeed)));
  (p.rfqIds || []).map(id => byId('purchases', id)).filter(Boolean).forEach(x => rows.push(row(x)));
  const ph = p.rfqPhoto ? `<div class="rfqfromneed" style="margin-top:8px"><div class="small muted">صورة من القسم الطالب</div><img src="${esc(p.rfqPhoto)}" alt="" data-action="lightboxSrc" data-arg="${esc(p.rfqPhoto)}"></div>` : '';
