  const fz = typeof factoryZone === 'function' ? factoryZone() : null; add('Ninety', 'factory', 'المصنع', fz || {});
  try { const oc = officeCfg(); if (hasLL(oc)) add('Ninety', 'office', 'المكتب', oc); } catch (e) { /* ignore */ }
  sortBy(list('servfactories'), x => x.name || '').forEach(x => { add('المصانع الخدمية', `sf:${x.id}`, x.name, x); (x.branches || []).forEach(b => { if (b && b.name) add('المصانع الخدمية', `sf:${x.id}:${b.id}`, `${x.name} — ${b.name}`, hasLL(b) ? b : x); }); });
