/* ---------- 6) supplier wallet ---------- */
function supplierWallet(s) {
  const pos = list('purchases').filter(p => (p.supplierId && p.supplierId === s.id) || (!p.supplierId && (p.supplier || '').trim() === (s.name || '').trim()));
  const ids = new Set(pos.map(p => p.id)); const pays = sortBy(list('expenses').filter(e => e.purchaseId && ids.has(e.purchaseId)), e => e.date || '', true);
  const paid = r2(sum(pays, e => +e.amount || 0));
  const received = r2(sum(pos.filter(p => ['received', 'partial'].includes(p.status)), p => poTotal(p) - (typeof poRejectedValue === 'function' ? poRejectedValue(p) : 0)));
  const pending = r2(sum(pos.filter(p => ['transfer', 'ordered', 'arrived'].includes(p.status)), p => poTotal(p)));
  const hold = r2(sum(pos, p => (typeof poHold === 'function' ? poHold(p) : 0)));
  return { pos, pays, paid, received, pending, hold, balance: r2(paid - received) };
}
function supplierWalletCard(s) {
  const x = supplierWallet(s); const bal = x.balance;
  return `<div class="card" id="supwallet"><div class="cardhead"><h3>${icon('money')}محفظة المورد</h3><div class="grow"></div><span class="badge ${bal > 0.5 ? 'warn' : bal < -0.5 ? 'crit' : 'good'}">${bal > 0.5 ? `معاه لينا ${fmtMoney(bal)}` : bal < -0.5 ? `علينا له ${fmtMoney(-bal)}` : 'متسوّي'}</span></div>
    <div class="grid g4" style="gap:10px;margin-bottom:10px">${[['اتحوّل له', x.paid], ['قيمة المستلم', x.received], ['لسه ماوصلش', x.pending], ['مجمّد (مرفوض)', x.hold]].map(([l, v]) => `<div><div class="tiny muted">${l}</div><b class="num">${fmtMoney(v)}</b></div>`).join('')}</div>
    ${x.pays.length ? `<div class="tablewrap"><table><thead><tr><th>التاريخ</th><th>أمر الشراء</th><th>من</th><th class="n">المبلغ</th><th></th></tr></thead><tbody>${x.pays.map(e => { const p = byId('purchases', e.purchaseId); const th = e.thumb || (p && p.transfer && p.transfer.thumb); return `<tr><td>${fmtDate(e.date)}</td><td><a href="#/purchases/${e.purchaseId}"><span class="code">${esc(p ? p.number : '')}</span></a></td><td class="small">${esc(acctLabel(e.account))}</td><td class="n"><b>${fmtMoney(e.amount)}</b></td><td>${th ? `<img src="${th}" style="width:34px;height:34px;object-fit:cover;border-radius:6px">` : ''}</td></tr>`; }).join('')}</tbody></table></div>` : '<div class="muted small">لسه مفيش تحويلات للمورد ده</div>'}</div>`;
}
EXTRA_VIEWS.suppliers = (base => r => { let h = base(r); if (!r.id || !moneyOn() || !seesMoneyOps()) return h; const s = byId('suppliers', r.id); if (!s) return h; const i = h.indexOf('<div class="card"'); const card = supplierWalletCard(s); return i < 0 ? h + card : h.slice(0, i) + card + h.slice(i); })(EXTRA_VIEWS.suppliers);
/* PO transfer: pick where the money came from; the payment becomes a ledger entry (account = source) */
async function acctPurchaseOut(p, amt) {
  if (!p || !(+amt)) return; const src = S._poSrc || 'personal'; const n = list('expenses').filter(e => e.purchaseId === p.id).length + 1;
  await Store.save('expenses', { id: `pot_${p.id}_${n}`, date: todayISO(), month: monthOf(todayISO()), amount: +amt, cat: 'materials', account: src, orderId: null, payee: p.supplier || '', supplierId: p.supplierId || null, ref: p.number, note: `تحويل للمورد — ${p.number}`, src: 'purchase', purchaseId: p.id, thumb: (p.transfer && p.transfer.thumb) || null, byName: S.session?.name || '', createdAt: nowISO() }, { silent: true });
}
(() => { const base = ACTIONS.poTransfer; if (!base) return; ACTIONS.poTransfer = async id => {
  const p = byId('purchases', id); if (!p || !isAdmin() || !moneyOn()) return base(id);
  const pre = S._poSrcPre || null; /* v7.73: already picked in the transfer window (supplier-pay) → no second window */
  const src = pre || await new Promise(res => { let d = false; const fin = v => { if (!d) { d = true; clearInterval(iv); res(v); } }; openModal({ title: `تحويل ${fmtMoney(poPayable(p))} ${CUR()} — ${p.supplier || ''}`, submitLabel: 'التالي: صورة التحويل', body: `<div class="form">${field('التحويل من', `<select name="src">${srcOptions('personal')}</select>`, 'full')}</div>`, onSubmit: f => { fin(formData(f).src || 'personal'); return true; } }); const iv = setInterval(() => { if (!document.getElementById('mform')) fin(null); }, 300); });
  if (!src) return; const w = walletOf(src); if (w && walletBalance(w.id).balance + 0.5 < poPayable(p)) { toast(`رصيد عهدة ${w.name} مش كفاية`, 'err'); return; }
  if (!pre) await new Promise(r => setTimeout(r, 350)); S._poSrc = src;
  try { await base(id); } finally { S._poSrc = null; }
  const p2 = byId('purchases', id); if (p2 && p2.transfer && !p2.transfer.source) await Store.update('purchases', id, { transfer: Object.assign({}, p2.transfer, { source: src, sourceName: acctLabel(src) }) });
  const e = list('expenses').find(x => x.purchaseId === id && x.src === 'purchase' && !x.thumb); if (e && p2 && p2.transfer && p2.transfer.thumb) await Store.update('expenses', e.id, { thumb: p2.transfer.thumb });
}; })();

