  const res = await moneyDialog({ title: `تحويل — ${catLabel(r.cat)}${r.homeId ? ' · ' + homeName(r.homeId) : ''}`, intro: `${fmtMonth(r.month)} — ${esc(r.payee || '')} — وافق عليه ${esc(r.decidedByName || 'مدير الحسابات')}`, amount: r.amount, fields: field('التحويل من', `<select name="src">${srcOptions('personal')}</select>`), fileRequired: false, submitLabel: 'تم التحويل', ownerKind: 'request', ownerId: r.id });
  if (!res) return; const w = walletOf(res.src); if (w && walletBalance(w.id).balance + 0.5 < res.amount) { toast(`رصيد عهدة ${w.name} مش كفاية`, 'err'); return; }
  await Store.save('expenses', { id: `opx_${r.id}`, date: todayISO(), month: r.month || monthOf(todayISO()), amount: res.amount, cat: r.cat, account: res.src, homeId: r.homeId || null, orderId: null, payee: r.payee || '', ref: '', note: `مصروف تشغيل — ${r.reason || ''}${res.note ? ' · ' + res.note : ''}`, src: 'opex', reqId: r.id, fileIds: (r.fileIds || []).concat(res.fileIds || []), thumb: r.thumb || res.thumb || null, byName: S.session?.name || '', createdAt: nowISO() });
