  Object.values(map).forEach(r => { r.reserved = r2(sum(Object.values(r.byOrder), q => Math.max(0, q))); r.available = r2(r.onHand - r.reserved - r.pendingFree); r.onHand = r2(r.onHand); const mn = byId('fgs', 'min_' + r.key); r.min = mn ? +mn.min || 0 : 0; });
