function fgVisibleRows() { const bs = fgBrands(); return Object.values(fgStock()).filter(r => r.onHand > 0.001 || r.min > 0 || r.reserved > 0).filter(r => { if (!bs) return true; const p = fgProd(r.productId); return p && bs.includes(p.brandId); }); }
const nextDnNo = () => { const y = todayISO().slice(2, 4); const n = fgDns().filter(d => (d.number || '').startsWith(`DN-${y}-`)).length + 1; return `DN-${y}-${String(n).padStart(3, '0')}`; };
function prodOptions(sel) { const bs = fgBrands(); return sortBy(list('products').filter(p => p.status !== 'inactive' && (!bs || bs.includes(p.brandId))), p => (p.brandId || '') + (p.code || '')).map(p => `<option value="${p.id}" ${p.id === sel ? 'selected' : ''}>${esc(brandName(p.brandId))} · ${esc(p.code || '')} ${esc(p.name || '')}</option>`).join(''); }
function orderOptions(sel) { return sortBy(list('orders').filter(o => o.status !== 'cancelled' && o.status !== 'delivered'), o => o.code || '').map(o => `<option value="${o.id}" ${o.id === sel ? 'selected' : ''}>${esc(o.code || '')} — ${esc(o.title || '')} · ${esc(clientName(o.clientId))}</option>`).join(''); }
