      if (oo) { try { await notifyRole('manager', `دخل المخزن جاهز: ${fgName(d.productId, d.variant)} × ${q}`, `محجوز لأمر ${oo.code} — ${clientName(oo.clientId)}`, { id: `fgin_${uid()}`, orderId: oo.id }); } catch (e) { /* ignore */ } }
