  if (!dn || dn.status === 'delivered') return;
  for (let i = 0; i < (dn.items || []).length; i++) { const it = dn.items[i]; const mid = `dnout_${dn.id}_${i}`; if (!byId('fgs', mid)) await Store.save('fgs', { id: mid, type: 'mv', kind: 'out', key: fgKey(it.productId, it.variant), productId: it.productId, variant: it.variant || '', qty: +it.qty || 0, orderId: dn.orderId || null, clientId: dn.clientId || null, dnId: dn.id, date: todayISO(), month: monthOf(todayISO()), at: nowISO(), byName: (proof && proof.byName) || S.session?.name || '', note: `تسليم ${dn.number}` }, { silent: true }); }
