  openModal({ title: `جرد — ${fgName(r.productId, r.variant)}`, body: `<div class="form"><div class="small full">الرصيد في السيستم: <b>${fmtNum(r.onHand)}</b></div>${field('العدد الفعلي في المخزن', inp('actual', r.onHand, 'type="number" min="0" step="1" required'))}${field('الحد الأدنى (تنبيه)', inp('min', r.min || '', 'type="number" min="0" step="1"'))}${field('السبب', inp('note', ''), 'full')}</div>`,
    onSubmit: async f => { const d = formData(f); const diff = Math.round(num(d.actual)) - r.onHand; if (diff && !(d.note || '').trim()) { toast('اكتب سبب الفرق', 'err'); return false; } if (diff) await fgMove({ kind: 'adj', productId: r.productId, variant: r.variant, qty: diff, note: `جرد: ${d.note}` }); await Store.save('fgs', { id: 'min_' + key, type: 'min', key, min: Math.round(num(d.min)) || 0 }, { silent: true }); toast('تم'); } });
