      if (pe) { await finSaveFix('@' + id, r.fix); const P = JSON.parse(JSON.stringify(finPrices())); P.sheenPct = Object.assign({}, FIN_DEFAULT_PRICES.sheenPct, P.sheenPct || {}, { [id]: num(d.pct) || 0 }); await Store.save('finish', Object.assign(P, { id: 'prices', updatedAt: nowISO(), byName: (S.session && S.session.name) || '' }), { silent: true }); }
