  const c = finCost($('#fa-sys', f).value, $('#fa-g', f).value, ($('#fa-sh', f) || {}).value); if (!c) return; const desc = `دهان ${c.sys.name} ${finSheenName(c.sheen)} — خامات ${finGradeName(c.grade)}`;
