  if (!row) { const n = $$('tbody tr', tbl).length; tbl.querySelector('tbody').insertAdjacentHTML('beforeend', `<tr><td><input name="est-desc-${n}"></td><td><input name="est-qty-${n}" type="number" step="any" min="0"></td><td><input name="est-unit-${n}"></td><td><input name="est-cost-${n}" type="number" step="any" min="0"></td><td class="n num">0</td></tr>`); row = tbl.querySelector('tbody tr:last-child'); }
