/* ---------- order page: «مراحل الدهان» ---------- */
const finCanJob = () => typeof writable === 'function' && writable() && (isAdmin() || ['hr', 'manager', 'head', 'tech', 'office'].includes(role()));
const finCanTick = () => typeof writable === 'function' && writable() && (isAdmin() || ['manager', 'head'].includes(role()));
function paintCard(o) {
  const jobs = o.paint || []; if (!jobs.length && !finCanJob()) return ''; const sp = finSeesProjectCost();
  const body = jobs.map(j => { const s = finSys(j.sys) || { name: j.sysName || j.sys, stages: j.stages || [] }; const stages = j.stages || s.stages || []; const done = j.done || {}; const n = stages.filter((st, i) => done[i]).length; const pct = stages.length ? Math.round(n / stages.length * 100) : 0; const c = sp ? finCost(j.sys, j.grade, j.sheen) : null; const needs = finNeeds(j.sys, j.area, j.sheen);
    return `<div class="paintjob"><div class="row" style="gap:8px;flex-wrap:wrap"><b>${esc(s.name)}</b>${j.sheen ? `<span class="badge">${esc(finSheenName(j.sheen))}</span>` : ''}<span class="badge">خامات ${finGradeName(j.grade)}</span><span class="small">${fmtNum(j.area)} م²</span>${j.desc ? `<span class="small muted">${esc(j.desc)}</span>` : ''}<div class="grow"></div><span class="small">${n}/${stages.length} مرحلة</span>${c ? `<span class="small">التكلفة التقديرية <b>${finMoney(c.total * j.area)}</b></span>` : ''}${finCanJob() ? `<button class="iconbtn" data-action="paintDel" data-arg="${o.id}|${j.id}" title="حذف">${icon('trash')}</button>` : ''}</div>
      <div class="bar"><i style="width:${pct}%"></i></div>
      <div class="stg">${stages.map((st, i) => `<button type="button" class="${done[i] ? 'on' : ''}" ${finCanTick() ? `data-action="paintTick" data-arg="${o.id}|${j.id}|${i}"` : 'disabled'} title="${done[i] ? esc(`${done[i].byName || ''} · ${fmtDate((done[i].at || '').slice(0, 10))}`) : ''}">${done[i] ? '✓ ' : ''}${esc(st.name)}</button>`).join('')}</div>
      ${needs.length ? `<div class="tiny muted" style="margin-top:8px">الخامات المتوقعة: ${needs.map(x => `${esc(x.name)} ${fmtNum(x.qty)} ${esc(x.unit)}`).join(' · ')} · وقت الشغل حوالي ${finMin((finCost(j.sys, j.grade, j.sheen) || { minutes: 0 }).minutes * j.area)}</div>` : ''}</div>`; }).join('');
  return `<div class="card" id="paintcard"><div class="cardhead"><h3>${icon('layers')}مراحل الدهان</h3><div class="grow"></div>${finCanJob() ? `<button class="btn sm" data-action="paintNew" data-arg="${o.id}">${icon('plus')}شغل دهان</button>` : ''}</div>${body || '<div class="small muted">مفيش شغل دهان على الأمر ده — ضيف نوع التشطيب والمساحة، والمراحل تنزل لرئيس القسم يعلّم عليها.</div>'}</div>`;
}
RENDER_HOOKS.push(() => { if (!finOn() || S.route.view !== 'orders' || !S.route.id) return; const o = byId('orders', S.route.id); if (!o) return; const v = document.getElementById('view'); if (!v || v.querySelector('#paintcard')) return; const h = paintCard(o); if (!h) return; const fg = v.querySelector('#fgordercard'); if (fg) fg.insertAdjacentHTML('beforebegin', h); else v.insertAdjacentHTML('beforeend', h); });
ACTIONS.paintNew = oid => {
  const o = byId('orders', oid); if (!o || !finCanJob()) return; const C = finCfg();
  openModal({ title: `شغل دهان — ${o.code}`, body: `<div class="form">${field('نوع التشطيب', `<select name="sys">${C.systems.map(s => `<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select>`)}${field('درجة الخامات', `<select name="grade">${FIN_GRADES.map(g => `<option value="${g[0]}">${g[1]}</option>`).join('')}</select>`)}${field('درجة اللمعة', `<select name="sheen">${finSheens().map(x => `<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select>`)}${field('المساحة (م²)', inp('area', '', 'type="number" min="0" step="any" inputmode="decimal" required'))}${field('على إيه', inp('desc', '', 'placeholder="مثال: ضلف المطبخ + الدولاب"'))}</div>`,
    onSubmit: async f => { const d = formData(f); const area = num(d.area); if (!area) { toast('اكتب المساحة', 'err'); return false; } const s = finSys(d.sys); const job = { id: uid(), sys: d.sys, sysName: s ? s.name : d.sys, grade: d.grade, sheen: d.sheen || 'matte', area, desc: (d.desc || '').trim(), stages: s ? JSON.parse(JSON.stringify(s.stages.concat(finSheenStages(s, d.sheen || 'matte')).map(({ sheen, ...st }) => st))) : [], done: {}, at: nowISO(), byName: (S.session && S.session.name) || '' }; await Store.update('orders', oid, { paint: (o.paint || []).concat([job]) }); toast('اتضاف شغل الدهان ✓'); } });
};
ACTIONS.paintTick = async arg => {
  const [oid, jid, i] = String(arg || '').split('|'); const o = byId('orders', oid); if (!o || !finCanTick()) return; const jobs = JSON.parse(JSON.stringify(o.paint || [])); const j = jobs.find(x => x.id === jid); if (!j) return;
  j.done = j.done || {}; if (j.done[i]) delete j.done[i]; else j.done[i] = { at: nowISO(), by: (S.session && S.session.id) || null, byName: (S.session && S.session.name) || '' };
  await Store.update('orders', oid, { paint: jobs });
};
ACTIONS.paintDel = async arg => { const [oid, jid] = String(arg || '').split('|'); const o = byId('orders', oid); if (!o || !finCanJob()) return; if (!(await confirmDlg('حذف شغل الدهان ده؟', 'حذف'))) return; await Store.update('orders', oid, { paint: (o.paint || []).filter(x => x.id !== jid) }); };
Object.assign(window, { finCost, finNeeds, finCfg, finPrices });

