const BP_HIDDEN_KINDS = ['drawing', 'model', 'html'];
const bpImgFiles = p => filesOf('product', p.id).filter(f => !BP_HIDDEN_KINDS.includes(f.kind));
const bpCover = p => { const fs = bpImgFiles(p); const c = p.coverFileId ? fs.find(f => f.id === p.coverFileId) : null; if (c && c.thumb) return c.thumb; const t = fs.find(f => f.thumb); return t ? t.thumb : null; };
const bpBrand = () => (typeof CRM_BRAND === 'function' ? CRM_BRAND() : 'lof');
const bpProducts = b => sortBy(list('products').filter(p => p.brandId === b && p.status !== 'archived' && p.kind !== 'project' && !(typeof isFamilyItem === 'function' && isFamilyItem(p))), p => p.code || p.name);
const bpColl = p => (typeof productCollection === 'function' ? productCollection(p) : '') || '';
const bpCollName = (b, id) => (id && typeof collName === 'function' ? collName(b, id) : '') || 'بدون قسم';
const bpPrice = p => (+p.price ? `${fmtMoney(+p.price)} ${CUR()}` : '');
const bpCanList = () => isBdd() || isAdmin() || role() === 'tech';

canSee = (base => view => (view === 'products' && isBdd() ? true : base(view)))(canSee);
setTimeout(() => { if (Array.isArray(ROLE_VIEWS.bdd) && !ROLE_VIEWS.bdd.includes('products')) ROLE_VIEWS.bdd.push('products'); }, 0);

function vBddProducts() {
  const b = bpBrand(); const f = S.ui.filter.bprod ||= { coll: '' }; const q = (S.ui.search.products || '').toLowerCase();
  let arr = bpProducts(b); if (f.coll) arr = arr.filter(p => (bpColl(p) || '_') === f.coll); if (q) arr = arr.filter(p => `${p.code} ${p.name} ${p.dims || ''}`.toLowerCase().includes(q));
  const colls = (typeof brandCollections === 'function' ? brandCollections(b) : []).concat([{ id: '_', name: 'بدون قسم' }]);
  return `<div class="toolbar"><div class="seg"><button class="${!f.coll ? 'on' : ''}" data-action="bpFilter" data-arg="">الكل</button>${colls.map(c => `<button class="${f.coll === c.id ? 'on' : ''}" data-action="bpFilter" data-arg="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div><div class="grow"></div><div class="search">${icon('search')}<input placeholder="بحث بالكود أو الاسم" data-search="products" value="${esc(S.ui.search.products || '')}"></div><button class="btn p" data-action="bpList">${icon('print')}لستة منتجات</button></div>
    ${arr.length ? `<div class="bpgrid">${arr.map(p => { const c = bpCover(p); return `<a class="bpc" href="#/products/${p.id}"><div class="im">${c ? `<img src="${esc(c)}" alt="" loading="lazy">` : icon('inventory')}</div><div class="bd"><span class="code">${esc(p.code || '')}</span><b>${esc(p.name || '')}</b>${p.dims ? `<span class="muted tiny">${esc(p.dims)}</span>` : ''}${bpPrice(p) ? `<span class="pr">${bpPrice(p)}</span>` : '<span class="tiny muted">السعر مش متسجل</span>'}</div></a>`; }).join('')}</div>` : '<div class="empty"><b>مفيش منتجات</b></div>'}`;
}
function vBddProductDetail(id) {
  const p = byId('products', id); const b = bpBrand(); if (!p || p.brandId !== b) return '<div class="empty"><b>المنتج غير موجود</b></div>';
  const imgs = bpImgFiles(p).filter(f => f.thumb); const c = bpCover(p);
  return `<div class="card"><div class="cardhead">${brandChip(p.brandId)}<h2 style="margin:0">${esc(p.name)}</h2><div class="grow"></div><span class="code">${esc(p.code || '')}</span></div>
    ${c ? `<img class="bpbig" src="${esc(c)}" alt="">` : ''}
    <div class="grid g4" style="gap:10px 14px;font-size:13px;margin-top:12px">
      <div><div class="tiny muted">القسم</div>${esc(bpCollName(b, bpColl(p)))}</div>
      ${p.dims ? `<div><div class="tiny muted">المقاسات</div>${esc(p.dims)}</div>` : ''}
      ${p.finish ? `<div><div class="tiny muted">التشطيب</div>${esc(p.finish)}</div>` : ''}
      <div><div class="tiny muted">السعر</div><b>${bpPrice(p) || '—'}</b></div></div>
    ${p.desc ? `<div class="sep"></div><div class="small" style="white-space:pre-wrap">${esc(p.desc)}</div>` : ''}
    ${p.materials ? `<div class="sep"></div><div class="tiny muted">الخامات</div><div class="small" style="white-space:pre-wrap">${esc(p.materials)}</div>` : ''}
    ${imgs.length > 1 ? `<div class="sep"></div><div class="bpgrid">${imgs.slice(0, 8).map(f => `<div class="bpc"><div class="im"><img src="${esc(f.thumb)}" alt="" loading="lazy" data-action="lightboxSrc" data-arg="${esc(f.thumb)}"></div></div>`).join('')}</div>` : ''}
  </div>`;
}
vProducts = (base => function () { return isBdd() ? vBddProducts() : base.apply(this, arguments); })(vProducts);
vProductDetail = (base => function (id) { return isBdd() ? vBddProductDetail(id) : base.apply(this, arguments); })(vProductDetail);
ACTIONS.bpFilter = v => { (S.ui.filter.bprod ||= {}).coll = v; render(false); };
/* owner / technical office: the list button on the normal products page */
RENDER_HOOKS.push(() => {
  if (!S.route || S.route.view !== 'products' || S.route.id || isBdd() || !bpCanList()) return; const tb = document.querySelector('#view .toolbar'); if (!tb || tb.querySelector('[data-action="bpList"]')) return;
  tb.insertAdjacentHTML('beforeend', `<button class="btn" data-action="bpList">${icon('print')}لستة منتجات</button>`);
});

/* ---- product list: PDF / Excel ---- */
function bpRows(b, coll) {
  const all = bpProducts(b); const colls = (typeof brandCollections === 'function' ? brandCollections(b) : []).map(c => c.id).concat(['']);
  const groups = []; colls.forEach(id => { if (coll && coll !== (id || '_')) return; const items = all.filter(p => bpColl(p) === id || (!id && !colls.includes(bpColl(p)))); if (items.length) groups.push({ id, name: bpCollName(b, id), items }); });
  return groups;
}
ACTIONS.bpList = () => {
  if (!bpCanList()) return; const b = isBdd() ? bpBrand() : ((S.ui.filter.products || {}).brand || bpBrand());
  const colls = (typeof brandCollections === 'function' ? brandCollections(b) : []);
  openModal({ title: 'لستة منتجات', body: `<div class="form">${field('البراند', `<b>${esc((S.settings.brands.find(x => x.id === b) || {}).name || b)}</b>`)}
      ${field('القسم', `<select id="bp-coll"><option value="">كل الأقسام</option>${colls.map(c => `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}<option value="_">بدون قسم</option></select>`)}
      <label class="field full" style="display:flex;gap:8px;align-items:center"><input type="checkbox" id="bp-price" checked> إظهار السعر</label></div>`,
    footer: `<button type="button" class="btn" data-action="closemodal">إلغاء</button><button type="button" class="btn" data-action="bpXlsx" data-arg="${esc(b)}">${icon('layers')}Excel</button><button type="button" class="btn p" data-action="bpPdf" data-arg="${esc(b)}">${icon('print')}PDF</button>` });
};
const bpOpts = () => ({ coll: ($('#bp-coll') || {}).value || '', price: !!($('#bp-price') || {}).checked });
ACTIONS.bpPdf = b => {
  const o = bpOpts(); const groups = bpRows(b, o.coll); if (!groups.length) { toast('مفيش منتجات في القسم ده', 'err'); return; } closeModal();
  const bn = (S.settings.brands.find(x => x.id === b) || {}).name || b;
  const html = `<div class="pl"><div class="hd">${typeof brandLogoHTML === 'function' ? brandLogoHTML(b, 44) : ''}<div><h1>لستة منتجات ${esc(bn)}</h1><div style="font-size:11px;color:#555">${esc(o.coll ? bpCollName(b, o.coll === '_' ? '' : o.coll) : 'كل الأقسام')} · ${fmtDate(todayISO())}</div></div></div>
    ${groups.map(g => `<h2>${esc(g.name)} (${g.items.length})</h2><table><thead><tr><th></th><th>الكود</th><th>المنتج</th><th>المقاسات</th><th>التشطيب</th>${o.price ? '<th>السعر</th>' : ''}</tr></thead><tbody>${g.items.map(p => { const c = bpCover(p); return `<tr><td class="im">${c ? `<img src="${esc(c)}" alt="">` : ''}</td><td>${esc(p.code || '')}</td><td><b>${esc(p.name || '')}</b>${p.materials ? `<div style="font-size:10px;color:#555">${esc(String(p.materials).slice(0, 120))}</div>` : ''}</td><td>${esc(p.dims || '')}</td><td>${esc(p.finish || '')}</td>${o.price ? `<td>${bpPrice(p) || '—'}</td>` : ''}</tr>`; }).join('')}</tbody></table>`).join('')}
    <div class="ft">${o.price ? 'الأسعار استرشادية وقابلة للتغيير — ' : ''}${esc(bn)}</div></div>`;
  printHTML(html); toast('من شاشة الطباعة اختار «حفظ كـ PDF»');
};
ACTIONS.bpXlsx = async b => {
  const o = bpOpts(); const groups = bpRows(b, o.coll); if (!groups.length) { toast('مفيش منتجات في القسم ده', 'err'); return; }
  const ok = typeof loadXLSX === 'function' ? await loadXLSX() : false; if (!ok || !window.XLSX) { toast('تعذّر تحميل Excel — جرّب تاني', 'err'); return; }
  const wb = XLSX.utils.book_new(); const used = new Set();
  groups.forEach(g => {
    const rows = [['الكود', 'المنتج', 'المقاسات', 'التشطيب', 'الخامات'].concat(o.price ? ['السعر (' + CUR() + ')'] : [])].concat(g.items.map(p => [p.code || '', p.name || '', p.dims || '', p.finish || '', p.materials || ''].concat(o.price ? [+p.price || ''] : [])));
    const ws = XLSX.utils.aoa_to_sheet(rows); ws['!cols'] = [{ wch: 16 }, { wch: 34 }, { wch: 24 }, { wch: 22 }, { wch: 40 }, { wch: 14 }]; ws['!views'] = [{ RTL: true }];
    let nm = String(g.name).replace(/[\\/?*[\]:]/g, ' ').slice(0, 31) || 'Sheet'; while (used.has(nm)) nm = nm.slice(0, 28) + '_' + used.size; used.add(nm);
    XLSX.utils.book_append_sheet(wb, ws, nm);
  });
  wb.Workbook = { Views: [{ RTL: true }] };
  const bn = (S.settings.brands.find(x => x.id === b) || {}).name || b;
  XLSX.writeFile(wb, `${bn}-products-${todayISO()}.xlsx`); closeModal(); toast('اتنزل ملف Excel ✓');
};
