ACTIONS.cxChkAns = async arg => { const [id, i, k] = String(arg).split(':'); const c = cxChkCollect(id); if (!c || !cxCheckEditable(c)) return; c.items[+i].ok = k === 'ok' ? true : k === 'no' ? false : null; await Store.save('checks', c); };
