    const team = stuPeople().filter(x => d['team-' + x.id]).map(x => x.id); if (d.leadId && !team.includes(d.leadId)) team.unshift(d.leadId);
    const doc = Object.assign({}, p, { name: d.name, client: d.client !== undefined ? d.client : (p.client || ''), code: d.code || p.code || ('NS-' + String(list('projects').length + 1).padStart(3, '0')), stage: d.stage, dueDate: d.dueDate || null, leadId: d.leadId || null, area: d.area || '', team, desc: typeof nfUnmaskMoney === 'function' ? nfUnmaskMoney(d.desc, p.desc) : d.desc, status: p.status || 'active' });
