  ACTIONS.stuProjectNew = () => { if (!stuCanEdit()) return; openModal({ title: 'مشروع جديد', wide: true, body: stuProjectForm({ team: [stuMe()].filter(Boolean) }), submitLabel: 'إنشاء المشروع', onSubmit: async f => { const p = await stuProjectSave(f, {}); if (!p) return false; await stuEnsureBoards(p.id); toast('اتعمل المشروع وبورداته'); go('projects/' + p.id); } }); };
  ACTIONS.stuProjectEdit = id => { const p = byId('projects', id); if (!p || !stuCanEdit()) return; openModal({ title: 'تعديل المشروع', wide: true, body: stuProjectForm(p), extra: stuManager() ? `<button type="button" class="btn d" data-action="stuProjectArchive" data-arg="${p.id}">أرشفة</button>` : '', onSubmit: async f => { await stuProjectSave(f, p); } }); };
  ACTIONS.stuProjectArchive = async id => { const p = byId('projects', id); if (!p || !stuManager()) return; if (!(await confirmDlg(`أرشفة مشروع «${p.name}»؟ يختفي من القائمة ويفضل محفوظًا.`, 'أرشفة'))) return; await Store.save('projects', Object.assign({}, p, { status: 'archived' })); closeModal(); go('projects'); };
  ACTIONS.stuStageSet = async arg => { const [pid, st] = arg.split(':'); const p = byId('projects', pid); if (!p || !(stuManager() || p.leadId === stuMe())) return; if (p.stage === st) return; await Store.save('projects', Object.assign({}, p, { stage: st, stageAt: Object.assign({}, p.stageAt || {}, { [st]: nowISO() }) })); toast(`المرحلة: ${stuStage(st).ar}`); };
