const WB = { id: null, zoom: 1, pan: { x: 0, y: 0 }, tool: 'select', sel: new Set(), drag: null, held: new Set(), editing: null, cursors: {}, chan: null, chanId: null, stroke: null, connFrom: null, panel: null, timerT: null };
const WB_COLORS = ['#f7e463', '#f9b48d', '#f19ea6', '#c9a9f5', '#9ad6f7', '#a6e6a1', '#e8e8e8'];
const WB_PEN = ['#f2f2f2', '#f2d16b', '#7fd6d6', '#f19ea6', '#9ad6f7'];
const stuBoardBusy = () => !!WB.drag || !!WB.stroke || !!WB.editing || (typeof DB !== 'undefined' && DB.drag);
const stuBoardHeld = (col, id) => col === 'bitems' && (WB.held.has(id) || (WB.editing === id));
const wbItems = () => list('bitems').filter(i => i.boardId === WB.id && !i.deleted);
const wbBoard = () => byId('boards', WB.id);
const wbCanEdit = () => { const b = wbBoard(); if (!b || !stuCanEdit()) return false; if (typeof nbRank === 'function') return nbRank(b) >= 3; /* v6.07 board roles */ if (b.personal) return b.ownerId === stuMe() || isAdmin(); return true; };
const wbCanSee = b => { if (!b) return false; if (typeof nbRank === 'function') return nbRank(b) >= 1; /* v6.07 board roles */ if (b.personal) return b.ownerId === stuMe() || isAdmin() || (b.shared || []).includes(stuMe()); const p = b.projectId ? byId('projects', b.projectId) : null; return p ? stuProjectVisible(p) : true; };
const wbW2S = (x, y) => ({ x: x * WB.zoom + WB.pan.x, y: y * WB.zoom + WB.pan.y });
const wbS2W = (sx, sy) => ({ x: (sx - WB.pan.x) / WB.zoom, y: (sy - WB.pan.y) / WB.zoom });
const wbRect = i => ({ x: +i.x || 0, y: +i.y || 0, w: +i.w || 160, h: +i.h || 160 });
