  function wbEditStart(id) { const it = byId('bitems', id); if (!it || !wbCanEdit()) return; WB.editing = id; const n = wbNode(id); const t = n && n.querySelector('.txt'); if (!t) return; t.setAttribute('contenteditable', 'true'); t.focus(); const r = document.createRange(); r.selectNodeContents(t); r.collapse(false); const s = getSelection(); s.removeAllRanges(); s.addRange(r); t.addEventListener('blur', wbEditEnd, { once: true }); }
