  /* ---------- actions ---------- */
  ACTIONS.wbZoom = arg => { const host = $('#wbwrap'); if (!host) return; if (arg === 'fit') { wbFit(); } else { const k = arg === '+' ? 1.2 : 1 / 1.2; const sx = host.clientWidth / 2, sy = host.clientHeight / 2; const w = wbS2W(sx, sy); WB.zoom = Math.min(4, Math.max(.08, WB.zoom * k)); WB.pan = { x: sx - w.x * WB.zoom, y: sy - w.y * WB.zoom }; } wbApplyView(); wbSelRender(); };
