  ACTIONS.wbEdit = id => { const it = byId('bitems', id); if (!it || !wbCanEdit()) return; if (it.type === 'link') return wbLinkDialog(null, it); if (it.type === 'frame') { openModal({ title: 'اسم الفريم', body: `<div class="form">${field('الاسم', inp('text', it.text || '', 'required'), 'full')}</div>`, onSubmit: async f => { it.text = formData(f).text; await wbSave(it); } }); return; } wbEditStart(id); };
