  ACTIONS.wbComment = async id => { const it = byId('bitems', id); const inp0 = $('#wbcin'); const text = (inp0 && inp0.value.trim()) || ''; if (!it || !text) return; it.thread = (it.thread || []).concat([{ id: uid(), at: nowISO(), by: stuMe(), byName: S.session?.name || '', text }]); await wbSave(it, true); inp0.value = ''; stuMentionNotify(text, `تعليق على «${(it.text || it.type).slice(0, 30)}» في ${wbBoard().title}`, `#/ideas/${WB.id}`); rerender(); };
  ACTIONS.wbTimerStart = () => { if (!wbCanEdit()) return; openModal({ title: 'تايمر السيشن', body: `<div class="form">${field('الدقائق', inp('min', '10', 'type="number" min="1" max="180"'))}</div>`, submitLabel: 'ابدأ', onSubmit: async f => { const m = Math.max(1, +formData(f).min || 10); await Store.save('boards', Object.assign({}, wbBoard(), { timer: { end: new Date(Date.now() + m * 60000).toISOString(), min: m, by: S.session?.name || '' } })); } }); };
