  ACTIONS.wbExport = () => { const b = wbBoard(); if (!b) return; wbFit(); wbApplyView(); document.body.classList.add('stuprint'); const p = b.projectId ? byId('projects', b.projectId) : null; const hdr = document.createElement('div'); hdr.id = 'stuprinthdr'; hdr.innerHTML = `<div style="display:flex;align-items:center;gap:12px;padding:10px 0 12px;border-bottom:1px solid #ddd;margin-bottom:10px;direction:rtl"><img src="${LOGO_MARK}" style="height:28px"><b>${esc(b.title)}</b><span style="color:#666">${p ? esc(p.name) + ' · ' : ''}${fmtDate(todayISO())} · Ninety Studioz</span></div>`; const v = $('#view'); if (v) v.prepend(hdr); setTimeout(() => { window.print(); setTimeout(() => { document.body.classList.remove('stuprint'); hdr.remove(); }, 500); }, 200); };
  ACTIONS.wbSendSel = async () => { const b = wbBoard(); if (!b || !WB.sel.size) { toast('حدّد عناصر الأول', 'err'); return; } const sel = [...WB.sel].map(id => byId('bitems', id)).filter(i => i && ['sticky', 'text', 'image', 'link'].includes(i.type)); if (!sel.length) { toast('المحدد مفيهوش ستيكي/نص/صورة/لينك', 'err'); return; } let target = null; if (b.projectId) { const bs = await stuEnsureBoards(b.projectId); target = bs.design; } else target = await stuEnsurePersonal('design'); if (!target) return; const col = (target.cols || [])[0] ? target.cols[0].id : 'c1'; let n = 0; for (const it of sel) { const card = { id: uid(), boardId: target.id, col, ord: Date.now() + n, by: stuMe(), byName: S.session?.name || '', fromIdeas: it.id }; if (it.type === 'image') Object.assign(card, { type: 'image', fileId: it.fileId, thumb: it.thumb, caption: '' }); else if (it.type === 'link') Object.assign(card, { type: 'link', url: it.url, title: it.text || '' }); else Object.assign(card, { type: 'note', title: '', text: it.text || '', color: it.color || null }); await Store.save('bitems', card, { silent: true }); it.sent = { boardId: target.id, at: nowISO() }; await wbSave(it, true); n++; } toast(`اتبعت ${n} للديزاين بورد`); rerender(); };
  window.stuMentionNotify = async (text, title, link) => { const names = [...text.matchAll(/@([^\s@]+)/g)].map(m => m[1]); if (!names.length) return; const ppl = stuPeople(); for (const nm of names) { const p = ppl.find(x => x.name.split(/\s+/)[0] === nm || x.name.replace(/\s+/g, '') === nm); if (!p || p.id === stuMe()) continue; const id = 'mention_' + uid(); await Store.save('tasks', { id, title: `${S.session?.name || ''} ذكرك: ${title}`.slice(0, 120), desc: text, assigneeId: p.id, kind: 'update', priority: 'normal', status: 'open', source: 'system', link, createdAt: nowISO(), updatedAt: nowISO() }, { silent: true }); } };

  /* ---------- presence: cursors of the others on this board ---------- */
  function wbPresence(boardId) {
    if (!S.sb || !boardId || WB.chanId === boardId) return; wbPresenceStop();
    try {
      const me = stuMe(); const ch = S.sb.channel('wb:' + boardId, { config: { presence: { key: me } } });
      if (!ch || typeof ch.track !== 'function' || typeof ch.presenceState !== 'function') { WB.chanId = boardId; return; } // test double without presence
      ch.on('presence', { event: 'sync' }, () => { const st = ch.presenceState(); WB.cursors = {}; Object.entries(st).forEach(([k, arr]) => { if (k === me) return; const c = arr[arr.length - 1]; if (c) WB.cursors[k] = Object.assign({ person: k }, c); }); wbCursorsRender(); const pr = document.querySelector('.wbpresence'); if (pr) pr.innerHTML = stuAvatar(me, 22) + Object.values(WB.cursors).map(c => stuAvatar(c.person, 22)).join(''); })
        .on('broadcast', { event: 'cur' }, ({ payload }) => { if (!payload || payload.person === me) return; WB.cursors[payload.person] = Object.assign(WB.cursors[payload.person] || { person: payload.person }, payload); wbCursorsRender(); })
        .subscribe(async status => { if (status === 'SUBSCRIBED') await ch.track({ name: S.session?.name || '', at: Date.now() }); });
      WB.chan = ch; WB.chanId = boardId;
    } catch (e) { console.warn('presence', e); }
  }
