  ACTIONS.dbToIdeas = async id => { const it = byId('bitems', id); const root = dbRoot(dbBoard()); if (!it || !root.projectId) return; const bs = await stuEnsureBoards(root.projectId); const wb = bs.ideas; const n = list('bitems').filter(x => x.boardId === wb.id).length; const base = { id: uid(), boardId: wb.id, x: 80 + (n % 6) * 200, y: 80 + Math.floor(n / 6) * 200, by: stuMe(), byName: S.session?.name || '', z: 1, fromDesign: it.id }; let doc; if (it.type === 'image') doc = Object.assign(base, { type: 'image', fileId: it.fileId, thumb: it.thumb, w: 280, h: 200 }); else if (it.type === 'link') doc = Object.assign(base, { type: 'link', url: it.url, text: it.title || '', w: 240, h: 76 }); else doc = Object.assign(base, { type: 'sticky', text: [it.title, it.text].filter(Boolean).join('\n'), color: it.color || WB_COLORS[0], w: 180, h: 180 }); await Store.save('bitems', doc, { silent: true }); toast('اتبعت لسبورة الأفكار'); };
