    host.addEventListener('dragstart', e => { const card = e.target.closest('.dbc'); if (!card || !dbCanEdit() || e.target.matches('[contenteditable="true"]')) { if (card) e.preventDefault(); return; } DB.drag = card.dataset.id; e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', card.dataset.id); } catch (x) { /* ignore */ } setTimeout(() => card.classList.add('ghost'), 0); });
