  /* ---------- render guard: never rebuild a board while its person is typing or dragging ---------- */
  const stuTyping = () => { const a = document.activeElement; return !!(a && a.closest && a.closest('#dbwrap [contenteditable="true"], #dbwrap input[data-dbcol], #wbwrap [contenteditable="true"], .wbpanel input, .dbpanel input')); };
