  document.addEventListener('focusout', () => { if (_stuDirty) setTimeout(() => { if (_stuDirty && !stuBoardBusy() && !stuTyping()) render(false); }, 120); });
  document.addEventListener('pointerup', () => { if (_stuDirty) setTimeout(() => { if (_stuDirty && !stuBoardBusy() && !stuTyping()) render(false); }, 150); });

