  function aiPalette(src) { return new Promise(res => { const im = new Image(); im.onload = () => { const c = document.createElement('canvas'); c.width = 48; c.height = 48; const x = c.getContext('2d'); x.drawImage(im, 0, 0, 48, 48); const d = x.getImageData(0, 0, 48, 48).data; const m = new Map(); for (let i = 0; i < d.length; i += 4) { const k = [(d[i] >> 4), (d[i + 1] >> 4), (d[i + 2] >> 4)].join(','); const e = m.get(k) || { n: 0, r: 0, g: 0, b: 0 }; e.n++; e.r += d[i]; e.g += d[i + 1]; e.b += d[i + 2]; m.set(k, e); } const arr = [...m.values()].sort((a, b) => b.n - a.n); const out = []; for (const e of arr) { const rgb = [e.r / e.n, e.g / e.n, e.b / e.n].map(Math.round); if (out.some(o => Math.abs(o[0] - rgb[0]) + Math.abs(o[1] - rgb[1]) + Math.abs(o[2] - rgb[2]) < 60)) continue; out.push(rgb); if (out.length >= 6) break; } res(out.map(([r, g, b]) => '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join(''))); }; im.onerror = () => res(['#1f2732', '#9fb3c8', '#d9c9a3']); im.src = src; }); }
