  if (typeof workerFormJobs === 'function') workerFormJobs = (base => function () { return base.apply(this, arguments).replace('label="الأقسام الإنتاجية"', 'label="أقسام التصميم"'); })(workerFormJobs);

  /* ---------- employee form wording ---------- */
  const stuWording = html => html
    .replace(/من المصنع( \/ المكتب)? — يبصم في (لوكيشن المصنع|الموقع)/g, 'من المكتب — يبصم في لوكيشن المكتب')
    .replace(/في المصنع/g, 'في المكتب').replace(/المصنع أو المكتب/g, 'المكتب')
