  const OS_GATES = [{ id: 'comp', en: 'Composition', ar: 'الكومبوزيشن' }, { id: 'light', en: 'Concept Lighting', ar: 'الإضاءة' }, { id: 'detail', en: 'Detailing + AI', ar: 'التفاصيل + AI' }, { id: 'post', en: 'Final Post', ar: 'البوست النهائي' }];
  const OS_CAUSES = { data: 'داتا ناقصة من العميل', client: 'قرار من العميل', drone: 'الدرون', tech: 'مشكلة تقنية', approval: 'مستني اعتماد', internal: 'تأخير داخلي' };
  const OS_TITLES = [
    { id: 'ceo', t: 'CEO & Co-Founder', grp: 'الإدارة' }, { id: 'ad', t: 'Co-Founder & Art Director', grp: 'الإدارة' },
    { id: 'avlead', t: 'ArchViz Team Lead', grp: 'ARCHVIZ' }, { id: 'senior', t: 'Senior 3D Artist / Visual Lead', grp: 'ARCHVIZ' }, { id: 'mid', t: 'Mid-Level 3D Artist', grp: 'ARCHVIZ' }, { id: 'jrp', t: 'Junior+ 3D Artist', grp: 'ARCHVIZ' }, { id: 'jr', t: 'Junior 3D Artist', grp: 'ARCHVIZ' },
    { id: 'intlead', t: 'Interior Lead', grp: 'INTERIOR' }, { id: 'hybrid', t: 'Hybrid Interior / Exterior 3D Artist', grp: 'INTERIOR' },
    { id: 'film', t: 'Film & Animation Artist', grp: 'MEDIA / CONTENT' }, { id: 'content', t: 'Content Creator', grp: 'MEDIA / CONTENT' }, { id: 'brand', t: 'Graphic / Brand Support', grp: 'MEDIA / CONTENT' },
  ];
  const pairOpts = (pairs, cur) => pairs.map(([v, l]) => `<option value="${esc(v)}" ${v === cur ? 'selected' : ''}>${esc(l)}</option>`).join('');
