  ['shots', 'stuorg'].forEach(c => { if (!COLS.includes(c)) COLS.push(c); S.data[c] = S.data[c] || new Map(); });
  Store.subscribeAll = (base => function () { base.call(this); const db = S.db; if (!db) return; for (const c of ['shots', 'stuorg']) { S.unsub.push(db.collection(c).onSnapshot(snap => { S.data[c] = new Map(snap.docs.map(d => [d.id, d.data()])); S.loaded[c] = true; rerender(); }, e => console.warn('snapshot', c, e))); } })(Store.subscribeAll);

  /* ---------- who is who ---------- */
  const me = () => (typeof stuMe === 'function' ? stuMe() : (S.session && (S.session.workerId || S.session.id))) || '';
  const meIds = () => { const st = S.session || {}; return [st.workerId, st.id].filter(Boolean); };
  const isMe = id => !!id && meIds().includes(id);
  const isAD = () => isAdmin() || role() === 'manager';
  const adIds = () => list('workers').filter(w => w.role === 'manager' && w.status !== 'inactive').map(w => w.id);
  /* names directory (RPC nf_people_dir: id / name / title only) — the art director and team leads can't read full worker records */
  let DIR = null, dirAsked = false;
  const loadDir = () => { if (dirAsked || !S.sb || !S.session) return; dirAsked = true; Promise.resolve(S.sb.rpc('nf_people_dir')).then(r => { if (r && Array.isArray(r.data)) { DIR = r.data; rerender(); } }).catch(() => { dirAsked = false; }); };
  const dirGet = id => { const k = String(id || '').replace(/^w:/, ''); return (DIR || []).find(x => x.id === k) || null; };
  const pName = id => { const p = typeof stuPerson === 'function' ? stuPerson(id) : null; if (p && p.name && p.name !== id) return p.name; const d = dirGet(id); if (d) return d.name; loadDir(); return p ? p.name : '—'; };
  const people = () => { const base = typeof stuPeople === 'function' ? stuPeople() : list('workers').filter(w => w.status !== 'inactive').map(w => ({ id: w.id, name: w.name })); if (base.length >= (DIR || []).length && base.length) return base; loadDir(); return DIR ? DIR.filter(x => !['admin'].includes(x.role)).map(x => ({ id: x.id, name: x.name, role: x.role })) : base; };
  const isOS = p => !!p && (p.flow === 'os' || !!p.ownerId || !!p.osStatus);
  const isOwner = p => !!p && isMe(p.ownerId);
  const canSchedule = p => writable() && (isAD() || isOwner(p));          // create / edit the master schedule (shots, dates, assignees)
  const canStatus = p => writable() && (isAD() || isOwner(p));
  const shotsOf = pid => sortBy(list('shots').filter(s => s.projectId === pid && !s.deleted && !s.movedTo), s => s.code || ''); // v6.09: shots moved into the project's task board live there now
  const pushTo = (ids, title, body, url) => { try { const to = []; (ids || []).filter(Boolean).forEach(id => { to.push(id, 'w:' + id); }); if (to.length && typeof pushSend === 'function') pushSend(Array.from(new Set(to)).filter(x => !isMe(x) && !isMe(x.replace(/^w:/, ''))), title, body, url, 'stuos'); } catch (e) { /* push is best effort */ } };

  /* ---------- dates: client deadline fixed, D-2 / D-1 internal (Friday is off) ---------- */
  const isFri = iso => new Date(iso + 'T00:00:00').getDay() === 5;
  const backWork = (iso, n) => { let d = iso; let k = 0; while (k < n) { d = addDays(d, -1); if (!isFri(d)) k++; } return d; };
  const d2 = p => (p && p.clientDeadline ? backWork(p.clientDeadline, 2) : null);
  const d1 = p => (p && p.clientDeadline ? backWork(p.clientDeadline, 1) : null);
  const gateDue = s => (s.gateDue && s.gateDue[s.gate]) || s.due || null;
  const shotLate = s => s.state !== 'done' && gateDue(s) && gateDue(s) < todayISO();
  const shotRisk = (s, p) => s.state !== 'done' && s.due && d2(p) && s.due > d2(p);
  const hoursSince = iso => iso ? Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 36e5)) : 0;
  const waitTxt = iso => { const h = hoursSince(iso); return h < 1 ? 'دلوقتي' : h < 24 ? `${h} س` : `${Math.round(h / 24)} يوم`; };
  const lastLog = (s, act) => (s.log || []).slice().reverse().find(l => !act || l.act === act);

  /* ---------- shot workflow ---------- */
  async function shotAct(id, act, note) {
    const s = byId('shots', id); if (!s) return; const p = byId('projects', s.projectId); if (!p) return;
    const now = nowISO(); const entry = { at: now, by: me(), act, gate: s.gate, note: note || '' }; const next = Object.assign({}, s, { log: (s.log || []).concat([entry]), updatedAt: now });
    const gi = OS_GATES.findIndex(g => g.id === s.gate); const gate = osGate(s.gate);
    const ownerIsAD = adIds().includes(p.ownerId) || !p.ownerId;
    if (act === 'submit') { next.state = 'owner'; next.submittedAt = now; if (ownerIsAD) next.state = 'ad'; pushTo(ownerIsAD ? adIds() : [p.ownerId], `طلب اعتماد: ${s.code} · ${gate.en}`, `${p.name} — ${pName(s.assigneeId)}`, `/#/projects/${p.id}`); }
    else if (act === 'ok1') { next.state = 'ad'; next.ok1At = now; pushTo(adIds(), `اعتماد نهائي مطلوب: ${s.code} · ${gate.en}`, `${p.name} — راجعه ${pName(me())}`, `/#/projects/${p.id}`); }
    else if (act === 'ok2') { if (gi >= OS_GATES.length - 1) { next.state = 'done'; next.doneAt = now; } else { next.gate = OS_GATES[gi + 1].id; next.state = 'work'; } pushTo([s.assigneeId], next.state === 'done' ? `اللقطة ${s.code} اتعتمدت نهائي ✓` : `اتعتمد ${gate.en} — ${s.code}`, next.state === 'done' ? p.name : `ابدأ ${osGate(next.gate).en}`, `/#/projects/${p.id}`); }
    else if (act === 'back') { next.state = 'work'; next.backs = (s.backs || 0) + 1; pushTo([s.assigneeId], `ملاحظات على ${s.code} · ${gate.en}`, note || p.name, `/#/projects/${p.id}`); }
    await Store.save('shots', next);
  }
