    const doc = Object.assign({ gate: 'comp', state: 'work', log: [], createdAt: nowISO(), createdBy: me() }, s, { projectId: p.id, code: d.code.trim(), name: d.name || '', kind: d.kind || 'still', assigneeId: d.assigneeId || null, gateDue: gateDueMap, due: d.due || null, updatedAt: nowISO() });
