    if (b.projectId) { if (r === 'manager') return 5; const p = byId('projects', b.projectId); const vis = ['hr', 'acc'].includes(r) || (p && ((p.team || []).some(has) || has(p.leadId) || has(p.ownerId) || has(p.createdBy))); if (vis) rk = Math.max(rk, RANK[(b.share && b.share.team) || 'edit'] || 0); return rk; }
