  const nameOf = id => { const p = (typeof stuPerson === 'function') ? stuPerson(id) : null; if (p && p.name && p.name !== id) return p.name; if (S.session && stuMeIds().includes(id)) return S.session.name || id; const w = byId('workers', id); return w ? w.name : (id === 'owner' ? 'المالك' : id); };
