  ACTIONS.pmFromCard = id => { const i = byId('bitems', id); if (!i) return; const bd = byId('boards', i.boardId); const root = bd && typeof dbRoot === 'function' ? dbRoot(bd) : bd; window.pmFromIdea({ projectId: root && root.projectId, text: [i.title, i.text, i.caption].filter(Boolean).join('\n'), fileId: i.type === 'image' ? i.fileId : null, thumb: i.type === 'image' ? i.thumb : null, src: 'design', boardId: i.boardId, itemId: i.id }); };
