  function vBurn(b) { return `<div class="dgrid"><div class="qcard" style="grid-column:1/-1"><h4>${L('منحنى تقدم المشروع (Burndown)', 'Project burndown')}</h4>${burnSVG(b)}</div><div class="qcard"><h4>${L('سرعة الفريق في المشروع ده', 'Team velocity on this project')}<small>${L('مهام خلصت كل أسبوع', 'tasks done per week')}</small></h4>${velBars(tasksOf(b))}</div><div class="qcard"><h4>${L('توقّع التسليم', 'Delivery forecast')}</h4>${(() => { const its = tasksOf(b); const left = its.filter(i => i.status !== 'done').length; const w0 = now() - 28 * 864e5; const rate = its.filter(i => (doneAt(i) || 0) >= w0).length / 4; const [, e] = boardSpan(b); if (!left) return `<p>${L('كل المهام خلصت ✓', 'All tasks are done ✓')}</p>`; if (!rate) return `<p class="muted">${L('لسه مفيش مهام خلصت في آخر 4 أسابيع عشان نتوقّع', 'No tasks finished in the last 4 weeks to forecast from')}</p>`; const wks = Math.ceil(left / rate); const fin0 = addD(TODAY(), wks * 7); const late = e && fin0 > e; return `<p>${L(`فاضل ${left} مهمة · بالسرعة الحالية (${rate.toFixed(1)}/أسبوع) هتخلص حوالي`, `${left} tasks left · at the current pace (${rate.toFixed(1)}/week) it finishes around`)} <b class="mono">${fmtD(fin0)}</b></p>${e ? `<p class="${late ? 'warnx' : ''}">${L('ميعاد التسليم', 'Due')}: <b class="mono">${fmtD(e)}</b>${late ? ' — ' + L('محتاج تسريع', 'needs speeding up') : ' ✓'}</p>` : ''}`; })()}</div></div>`; }
