    stageRows(b).slice(0, 9).forEach((r, i) => { const y = 3.6 + i * 0.4; T0(s, r[0], { x: rtl ? 9.4 : 0.6, y, w: 3, h: 0.35, fontSize: 12 }); const bx = rtl ? 0.9 : 3.8; s.addShape(P.ShapeType.rect, { x: bx, y: y + 0.08, w: 8.3, h: 0.2, fill: { color: 'EEEEEE' }, line: { color: 'EEEEEE' } }); const w = 8.3 * r[4] / 100; if (w > 0.01) s.addShape(P.ShapeType.rect, { x: rtl ? bx + 8.3 - w : bx, y: y + 0.08, w, h: 0.2, fill: { color: GOLD }, line: { color: GOLD } }); T0(s, r[4] + '%', { x: rtl ? 0.1 : 12.2, y, w: 0.8, h: 0.35, fontSize: 11, align: 'center' }); });
