  async function doExport(kind) { const b = curB(); if (!b) return; PM.pop = null; renderLayer(); toast(L('بيجهّز الملف…', 'Preparing the file…')); try { if (kind === 'xlsx') await expXlsx(b); else if (kind === 'docx') await expDocx(b); else await expPptx(b); toast(L('اتنزل الملف ✓', 'File downloaded ✓')); } catch (e) { console.warn('export', e); toast(String(e && e.message) === 'lib' ? L('مقدرتش أحمّل أداة التصدير — اتأكد من النت وجرّب تاني', 'Could not load the export tool — check the internet and try again') : L('حصل خطأ في التصدير', 'Export failed'), 'err'); } }

