    const b = curB(); const m = PM.meet = PM.meet || {}; m.busy = true; renderLayer();
    try { const j = await aiJ(`${CTXS}\nSummarise this meeting for the studio${b ? ` (project: ${bName(b)})` : ''}. Today is ${TODAY()}. Team: ${people().map(p => p.name).join(', ')}.\nGive a short summary, the decisions, and the action items (task, owner from the team if named, due date if said). Never mention money. ${LANG()}\nTranscript / notes:\n${x.slice(0, 12000)}\nReturn JSON only: {"summary":"…","decisions":["…"],"items":[{"name":"…","owner":"…","due":"YYYY-MM-DD"}]}`); m.res = { summary: String(j.summary || ''), decisions: (j.decisions || []).slice(0, 15).map(String), items: (j.items || []).filter(i => i && i.name).slice(0, 20) }; }
    catch (e) { toast(AI_ERR(e), 'err'); }
