    const picks = m.res ? (m.res.items || []).filter((_, k) => { const c = document.querySelector(`#pmlayer [data-mi="${k}"]`); return c && c.checked; }) : []; let n = 0;
    for (const a of picks) { const g = b0.groups[0]; const p = findPerson(a.owner); const it = mkTask(b0, g.id, String(a.name).slice(0, 160), { owner: p ? p.id : null, start: TODAY(), due: /^\d{4}-\d{2}-\d{2}$/.test(a.due || '') ? a.due : null }); logIt(it, 'meet', title || 'meeting'); await save(it); if (p) notify(p.id, { type: 'assigned', item: it.id, board: b0.id }); n++; }
