  const canPay = () => isAdmin() || ['acc', 'hr'].includes(role());
  const canDeliver = () => isAdmin() || isUpHead() || role() === 'manager';
  window.nfCanPiece = canPJ;
  const R2 = n => Math.round((+n || 0) * 100) / 100;
  const jTotal = j => R2(sum(j.items || [], it => (+it.qty || 0) * (+it.price || 0)));
  const jEarned = j => R2(sum(j.items || [], it => Math.min(+it.qty || 0, +it.done || 0) * (+it.price || 0)));
  const jPaid = j => R2(sum(j.payments || [], p => +p.amount || 0));
