    return `<div class="card tight"><div class="tablewrap"><table><thead><tr><th>الصنايعي</th><th>التخصص</th><th>التليفون</th><th class="n">اتفاقات</th><th class="n">متفق عليه</th><th class="n">اشتغل بـ</th><th class="n">اتصرفله</th><th class="n">فاضله</th><th></th></tr></thead><tbody>${cs.map(c => { const s = crafterStats(c); return `<tr><td><b>${esc(c.name)}</b>${c.active === false ? ' <span class="badge">موقوف</span>' : ''}</td><td>${esc(c.trade || '')}</td><td class="ltr">${esc(c.phone || '')}</td><td class="n">${s.n}</td><td class="n">${fmtMoney(s.agreed)}</td><td class="n">${fmtMoney(s.earned)}</td><td class="n">${fmtMoney(s.paid)}</td><td class="n" style="${s.bal > 0 ? 'color:var(--crit-ink);font-weight:600' : ''}">${fmtMoney(s.bal)}</td><td class="n">${writable() ? `<button class="iconbtn" data-action="crafterEdit" data-arg="${esc(c.id)}" title="تعديل">${icon('edit')}</button>` : ''}</td></tr>`; }).join('')}</tbody></table></div></div>`;
