  /* v7.47: a supplier transfer picture whose reading finished after the payment was recorded — fill the PO (and its
     expense) in: reference, the matched number, the screenshot link, and «matches / does not match» */
  async function supPatch(r, ctx, n) {
    const job = ctx && ctx.job; const ids = (ctx && (ctx.poIds || [ctx.poId])) || []; let hit = 0;
    for (const pid of ids) {
      const p = byId('purchases', pid); if (!p) continue;
      const ms = (window.nfSupPayOf && p.supplierId && (window.nfSupPayOf(p.supplierId) || {}).methods) || [];
      const m = ms.find(x => x && x.id === r.methodId) || null;
      const fix = x => (x && x.trfJob === job ? Object.assign({}, x, { ref: x.ref || r.ref || '', proofUrl: r.proofUrl || x.proofUrl || null, proofPath: r.proofPath || x.proofPath || null, aiOk: !!r.ok, aiIssues: r.issues || [], methodId: r.methodId || x.methodId || null, methodLabel: m ? mLabel(m) : (x.methodLabel || ''), trfPending: false }) : x);
      const upd = {};
      if (p.transfer && p.transfer.trfJob === job) upd.transfer = fix(p.transfer);
      if (p.deferred && (p.deferred.payments || []).some(x => x && x.trfJob === job)) upd.deferred = Object.assign({}, p.deferred, { payments: p.deferred.payments.map(fix) });
      if (Object.keys(upd).length) { hit++; try { await Store.update('purchases', pid, upd, { silent: true }); } catch (e) { /* ignore */ } }
      if (r.ref) { const e = list('expenses').find(x => x.purchaseId === pid && !x.trfRef && (x.src === 'purchase' || x.src === 'wallet')); if (e) { try { await Store.update('expenses', e.id, { trfRef: r.ref }, { silent: true }); } catch (e2) { /* ignore */ } } }
    }
    if (!hit && (n || 0) < 4) { setTimeout(() => supPatch(r, ctx, (n || 0) + 1), 4000); return; }
    if (hit) toast(r.ok ? L('صورة تحويل المورد اتراجعت ✓ — مطابقة', 'The supplier transfer picture is checked ✓ — it matches') : L('صورة تحويل المورد اتراجعت — فيها اختلاف، افتح الأمر', 'The supplier transfer picture is checked — something differs, open the PO'), r.ok ? undefined : 'err');
  }
  window.nfSupPatch = supPatch;
  if (window.nfTrf) nfTrf.on('posup', (r, ctx) => supPatch(r, ctx));
