  function nextCode(brand) { const pre = `${String(brand || 'NF').toUpperCase().slice(0, 3)}-Q`; const n = list('products').filter(p => String(p.code || '').startsWith(pre)).length + 1; let c = `${pre}${String(n).padStart(3, '0')}`; let i = n; while (list('products').some(p => (p.code || '').toLowerCase() === c.toLowerCase())) { i++; c = `${pre}${String(i).padStart(3, '0')}`; } return c; }
