    try { const cat = f && f.querySelector('#nibox #ni-cat'); if (cat && !f.querySelector('[data-catbox="ni-cat"]')) cat.insertAdjacentHTML('afterend', catBox('ni-cat')); } catch (e) { /* ignore */ }
