  document.addEventListener('change', async e => { const code = e.target.dataset && e.target.dataset.catren; if (!code || !canCats()) return; const label = e.target.value.trim(); if (!label) return; const old = byId('itemcats', 'cat_' + code) || { id: 'cat_' + code, code, createdAt: nowISO() }; await Store.save('itemcats', Object.assign({}, old, { label, deleted: false, renamedAt: nowISO() }), { silent: true }); syncCats(); toast('اتغير الاسم'); });
  document.addEventListener('click', async e => { const b = e.target.closest && e.target.closest('[data-catdel]'); if (!b || !canCats()) return; const code = b.dataset.catdel; if (BUILTIN.includes(code) || list('materials').some(m => m.itemCat === code)) { toast('الفئة عليها أصناف', 'err'); return; } if (!(await confirmDlg(`مسح الفئة ${code}؟`, 'امسح'))) return; const d = byId('itemcats', 'cat_' + code); if (d) await Store.save('itemcats', Object.assign({}, d, { deleted: true }), { silent: true }); syncCats(); render(false); });
  RENDER_HOOKS.push(() => { try { syncCats(); } catch (e) { /* ignore */ } });

