    list('materials').forEach(m => { if ((m.suppliers || []).some(x => x.supplierId === s.id) || (m.supplier && m.supplier.trim() === String(s.name || '').trim())) (window.nfItemDeptCodes ? window.nfItemDeptCodes(m) : [m.deptCode]).forEach(c => c && c !== 'MX' && set.add(c)); });
