    const hid = f && f.querySelector('#f-supDepts'); let codes = null; if (hid) { try { codes = JSON.parse(hid.value || '[]'); } catch (e) { codes = null; } }
    const doc = await base.apply(this, arguments); if (doc && doc.id && codes) await Store.update('suppliers', doc.id, { deptCodes: codes }); return doc;
