    const sel = `<select class="sel" data-sdept="1" style="max-width:190px"><option value="">كل الأقسام</option>${deptCodesList().map(x => `<option value="${esc(x.c)}" ${want === x.c ? 'selected' : ''}>${esc(x.n)}</option>`).join('')}<option value="__none" ${want === '__none' ? 'selected' : ''}>من غير قسم</option></select>`;
