    const w1 = XLSX.utils.aoa_to_sheet(a); w1['!cols'] = [{ wch: 28 }, { wch: 16 }, { wch: 14 }, { wch: 26 }, { wch: 14 }, { wch: 34 }]; w1['!views'] = [{ RTL: true }];
