  /* ---------- غلاف تلقائي لأي PDF من غير صورة (أول صفحة) — بيتحفظ على الملف لو المالك ---------- */
  const thumbMem = new Map(); const thumbBusy = new Set();
  const thumbOf = f => f.thumb || thumbMem.get(f.id) || '';
