    inp.onchange = async () => {
      const fs = [...(inp.files || [])]; let ok = 0; const miss = [];
      for (const f of fs) { const m = /S(\d{2})/i.exec(f.name); const code = m ? 'S' + m[1] : null; const doc = code && list('files').find(x => x.sim === p.sim && x.simShot === code); if (!doc) { miss.push(f.name); continue; }
        try { const st = await Files.put(f, f.type || 'image/jpeg'); await Store.save('files', Object.assign({}, doc, st, { size: f.size, mime: f.type || 'image/jpeg' }), { silent: true }); ok++; } catch (e) { miss.push(f.name); } }
      toast(isEn() ? `Uploaded ${ok} original images${miss.length ? ` · not matched: ${miss.length}` : ''}` : `اترفعت ${ok} صورة أصلية${miss.length ? ` · ماتطابقتش: ${miss.length}` : ''}`); render(false);
    };
    inp.click();
