  EXTRA_TITLES.pstory = () => { const p = S.route.id && byId('projects', S.route.id); return { title: isEn() ? 'Project story' : 'قصة المشروع', sub: p ? p.name : '', actions: p ? `<a class="btn ghost" href="#/projects/${esc(p.id)}">${icon('back')}<span>${isEn() ? 'Project page' : 'صفحة المشروع'}</span></a>` : '' }; };
