    box.addEventListener('scroll', () => { const nb = box.scrollHeight - box.scrollTop - box.clientHeight < 90; CONV.classList.toggle('up', !nb); if (nb) { PC.newBelow = 0; downBtn(); markRead(); } if (box.scrollTop < 60 && (msgs(PC.pid).length > PC.limit)) { PC.limit += 200; PC.keepTop = box.scrollHeight; msgRender(); } }, { passive: true });
    body.addEventListener('dragover', ev => { if ([...(ev.dataTransfer || {}).types || []].includes('Files')) { ev.preventDefault(); CONV.classList.add('drag'); } });
    body.addEventListener('dragleave', ev => { if (!body.contains(ev.relatedTarget)) CONV.classList.remove('drag'); });
