    CONV.querySelector('.pcfi-img').addEventListener('change', ev => { const fs = [...ev.target.files]; ev.target.value = ''; if (fs.length) previewFiles(fs); });
    CONV.querySelector('.pcfi-cam').addEventListener('change', ev => { const fs = [...ev.target.files]; ev.target.value = ''; if (fs.length) previewFiles(fs); });
