    box.addEventListener('touchmove', ev => { const t = ev.touches[0]; const dx = (t.clientX - sx) * (en() ? 1 : -1), dy = Math.abs(t.clientY - sy); if (lp && (Math.abs(t.clientX - sx) > 8 || dy > 8)) { clearTimeout(lp); lp = null; } if (srow && dy < 30 && dx > 0) srow.style.transform = `translateX(${(en() ? 1 : -1) * Math.min(70, dx)}px)`; }, { passive: true });
