    const c = convEl(); c.setAttribute('dir', en() ? 'ltr' : 'rtl'); c.dataset.pid = PC.pid;
    const hd = c.querySelector('.pch'); const h = headHTML(p); if (hd.__h !== h) { hd.__h = h; hd.innerHTML = h; }
    const pb = c.querySelector('.pcpinbar'); const ph = pinHTML(PC.pid); if (pb.__h !== ph) { pb.__h = ph; pb.innerHTML = ph; }
    const ta = c.querySelector('textarea'); const phd = L('اكتب رسالة', 'Type a message'); if (ta.placeholder !== phd) ta.placeholder = phd;
    if (c.__pid !== PC.pid) { c.__pid = PC.pid; ta.value = DRAFT.get(PC.pid) || ''; grow(ta); PC.reply = null; PC.edit = null; PC.side = null; PC.men = null; c.querySelector('.pcmsgs').__h = ''; typingSub(PC.pid); }
