    const m = base(pid, k, { f: Object.assign({ name: file.name, mime, size: file.size }, extra.f || {}) }); if (cap) { m.t = cap; const men = mentionIds(cap); if (men.length) m.men = men; }
    if (PC.reply && PC.pid === pid) { m.rep = PC.reply; PC.reply = null; repRender(); }
    if (k === 'img') { try { m.f.thumb = await fileToThumb(file, 640); } catch (e) { /* ignore */ } }
