  const emoList = s => (typeof Intl !== 'undefined' && Intl.Segmenter ? [...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(s)].map(x => x.segment) : Array.from(s.replace(/\ufe0f/g, '')));
  const emoRecent = () => { try { return JSON.parse(localStorage.getItem('pc.emoRecent') || '[]').slice(0, 27); } catch (e) { return []; } };
