    const rec = emoRecent(); const secs = (rec.length ? [{ k: 'r', n: L('المستخدمة مؤخرًا', 'Recent'), ic: '🕘', list: rec }] : []).concat(EMO.map((c, i) => ({ k: String(i), n: L(EMO_N[i][0], EMO_N[i][1]), ic: c[0], list: emoList(c[1]) })));
