    el.innerHTML = `<div class="pcet">${secs.map(x => `<button type="button" data-action="pcEmoTab" data-arg="${x.k}" title="${esc(x.n)}">${x.ic}</button>`).join('')}</div><div class="pcebody">${secs.map(x => `<div class="pces" data-sec="${x.k}"><div class="pcesh">${esc(x.n)}</div><div class="pceg">${x.list.map(e => `<button type="button" data-action="pcEmoPick" data-arg="${e}">${e}</button>`).join('')}</div></div>`).join('')}</div>`;
