    pcAttDoc: () => { closePops(); CONV.querySelector('.pcfi-doc').click(); }, pcAttImg: () => { closePops(); CONV.querySelector('.pcfi-img').click(); }, pcAttCam: () => { closePops(); CONV.querySelector('.pcfi-cam').click(); }, pcPoll: () => { closePops(); pollDialog(); },
