    pcRxMore: mid => { closePops(); PC.rxFor = mid; const el = CONV.querySelector('.pcrxbar'); el.innerHTML = `<div class="pceg wide">${emoList(EMO.map(x => x[1]).join('')).slice(0, 160).map(e => `<button type="button" data-action="pcReact" data-arg="${esc(mid)}|${e}">${e}</button>`).join('')}</div>`; el.className = 'pcrxbar on big'; popAt(el, CONV.querySelector(`[data-mid="${CSS.escape(mid)}"]`)); },
    pcReact: a => { const i = a.lastIndexOf('|'); react(a.slice(0, i), a.slice(i + 1)); if (PC.side === 'rx') sideRender(); },
    pcReply: mid => { const m = byM(PC.pid, mid); if (m) startReply(m); }, pcEdit: mid => { const m = byM(PC.pid, mid); if (m && canEdit(m)) startEdit(m); }, pcRepX: () => { PC.reply = null; if (PC.edit) { PC.edit = null; const ta = CONV.querySelector('textarea'); ta.value = DRAFT.get(PC.pid) || ''; grow(ta); sendBtn(); } repRender(); },
    pcCopy: async mid => { const m = byM(PC.pid, mid); closePops(); try { await navigator.clipboard.writeText(m.t || ''); toast(L('اتنسخت', 'Copied')); } catch (e) { toast(L('مقدرتش أنسخ', 'Could not copy'), 'err'); } },
    pcFwd: mid => { closePops(); fwdDialog(mid); }, pcTask: mid => { closePops(); makeTask(mid); },
