    pcJump: mid => { closePops(); jump(mid); }, pcEarlier: () => { const box = CONV.querySelector('.pcmsgs'); PC.limit += 200; PC.keepTop = box.scrollHeight; msgRender(); },
    pcBottom: () => { const box = CONV.querySelector('.pcmsgs'); box.scrollTo({ top: box.scrollHeight, behavior: 'smooth' }); PC.newBelow = 0; downBtn(); },
    pcSide: k => { closePops(); PC.side = k || null; if (k === 'search') PC.q = ''; sideRender(); }, pcMTab: k => { PC.mtab = k; sideRender(true); },
