    pcClear: async () => { closePops(); if (!(await confirmDlg(L('تمسح كل رسايل الجروب ده عندك إنت بس؟ الباقيين هيفضلوا شايفينها.', 'Clear all messages of this group for you only? The others still see them.'), L('امسح', 'Clear')))) return; saveR(PC.pid, { clr: now(), hid: [], rd: now() }); msgRepaint(); listRefresh(); },
    pcVote: a => { const i = a.lastIndexOf(':'); vote(a.slice(0, i), +a.slice(i + 1)); }, pcVotes: mid => { PC.side = 'votes'; PC.sideArg = mid; sideRender(); }, pcRxWho: mid => { closePops(); PC.side = 'rx'; PC.sideArg = mid; sideRender(); },
    pcWho: id => { PC.side = 'info'; sideRender(); },
