    pcOpenF: async mid => { const m = byM(PC.pid, mid); if (!m) return; const d = (m.f || {}).id && byId('files', m.f.id); if (d && ACTIONS.fileOpen && d.store !== 'thumb') { ACTIONS.fileOpen(d.id); return; } const u = await fileURL(m); if (u) { const a = document.createElement('a'); a.href = u; a.download = (m.f || {}).name || 'file'; a.target = '_blank'; a.rel = 'noopener'; document.body.appendChild(a); a.click(); a.remove(); } else toast(L('الملف مش متاح', 'File not available'), 'err'); },
