  Object.assign(ACTIONS, A);
  document.addEventListener('click', ev => { if (!CONV || !(PC.ctx || PC.emo || PC.att || PC.rxFor)) return; if (ev.target.closest('.pcctx,.pcemo,.pcatt,.pcrxbar,[data-action=pcCtx],[data-action=pcEmo],[data-action=pcAtt],[data-action=pcRxBar],[data-action=pcRxMore],[data-action=pcMenu]')) return; closePops(); }, true);
