(function () {
  if (window.__NF_AVS__) return; window.__NF_AVS__ = 1;
  window.nfPhoto = id => {
    id = String(id || '').replace(/^w:/, ''); if (!id) return null; const set = (S.settings && S.settings.avatars) || {};
    if (id === 'owner' || id === 'role:admin') return set.owner || (S.session && S.session.owner && S.session.avatar) || null;
    const w = byId('workers', id); if (w) return w.avatar || w.photo || null;
    const st = byId('staff', id); if (st) return st.avatar || st.photo || set[id] || null;
    return set[id] || null;
  };
  window.nfSil = () => '<svg class="nfsil" viewBox="0 0 212 212" aria-hidden="true"><path d="M106 50c-21.5 0-39 17.5-39 39s17.5 39 39 39 39-17.5 39-39-17.5-39-39-39zm0 92c-38 0-76 19-76 47v23h152v-23c0-28-38-47-76-47z"/></svg>';
  const css = document.createElement('style');
  css.textContent = `.pmav,.psav,.stuav,.pcav{overflow:hidden}
.pmav img,.psav img,.stuav img{width:100%;height:100%;border-radius:50%;object-fit:cover;display:block}
.nfsil{width:100%;height:100%;display:block;fill:#cfd4d6}
.pmav.sil,.psav.sil,.stuav.sil,.pcav.sil{background:#6a7175!important;padding:0}
html[data-theme="light"] .pmav.sil,html[data-theme="light"] .psav.sil,html[data-theme="light"] .stuav.sil,html[data-theme="light"] .pcav.sil{background:#dfe5e7!important}
html[data-theme="light"] .nfsil{fill:#fff}`;
  document.head.appendChild(css);
})();
