    openModal({ title: L('عميل جديد من الرسالة', 'New client from the message'), body: clientForm({ name: from.name && !/@/.test(from.name) ? from.name : dom.split('.')[0], contact: from.name || '', email: from.addr || '' }), onSubmit: async f => { const d = formData(f); if (!d.name) { toast(L('اكتب اسم العميل', 'Enter the client name'), 'err'); return false; } const c = await Store.save('clients', Object.assign({ id: uid(), email: from.addr || '' }, d)); await Store.save('mails', { id: `${MB.box}|${m.id}`.replace(/[^\w@.|-]/g, '_').slice(0, 120), box: MB.box, msgId: m.id, subject: m.subject || '', from: from.addr || '', fromName: from.name || '', at: m.at, clientId: c.id, projectId: null, webLink: m.webLink || null, byName: S.session && S.session.name || '', createdAt: nowISO() }, { silent: true }); toast(L('تمت إضافة العميل وربط الرسالة', 'Client added and the message linked')); rerender(); } });
