    const me = (S.session && S.session.name) || ''; const now = nowISO(); const patch = {};
    if (isAdmin()) Object.assign(patch, r.otMgrOk ? {} : { otMgrOk: true, otMgrBy: me, otMgrAt: now }, { otOk: true, otOkBy: me, otOkAt: now });
