      if (a.mode === 'checkin' && cur.errand && cur.errand.taskId === t.id) { row = Object.assign({}, cur, { in: null, method: null, src: 'errand-rejected', errand: Object.assign({}, cur.errand, { rejected: true }) }); if (!row.out) row.s = null; if (typeof computeAttRow === 'function') row = Object.assign(computeAttRow(row, w), { src: row.src, errand: row.errand, method: null }); if (!row.in && !row.out) { row.s = null; row.hrs = null; row.late = 0; } }
