    try { if (typeof pushSend === 'function' && t.assigneeId) pushSend(['w:' + t.assigneeId], L('بصمة المأمورية اترفضت', 'Errand punch rejected'), t.title, '/#/tasks/' + t.id, 'errand').catch(() => { }); } catch (e) { /* ignore */ }
    const n = byId('tasks', `errand_${t.id}`); if (n && n.status !== 'done') await Store.update('tasks', n.id, { status: 'done', doneAt: nowISO(), doneByName: (S.session || {}).name || '' }, { silent: true });
