  const NEAR_M = 60, FRESH_S = 180, SEND_MS = 30000;

  /* punched in today and not yet out */
  function punchedIn(wid) { try { const r = (typeof attendanceFor === 'function' ? attendanceFor(todayISO()) : {})[wid]; return !!(r && r.in && !r.out); } catch (e) { return false; } }
  const myTrip = () => (meId() ? list('trips').find(t => t.status === 'started' && t.driverId === meId()) : null);

