      try { DA.watcher = await BG().addWatcher({ backgroundTitle: L('Ninety · في الشغل', 'Ninety · at work'), backgroundMessage: L('بيحدّد مكانك أثناء الدوام — بيقف لوحده مع الانصراف', 'Locating you during the shift — stops by itself at punch-out'), requestPermissions: true, stale: false, distanceFilter: 15 }, (loc, err) => { if (err) { DA.locErr = err.code || 'err'; if (err.code === 'NOT_AUTHORIZED') DA.denied = true; return; } if (!loc || loc.latitude == null) return; DA.denied = false; take(loc.latitude, loc.longitude, loc.accuracy, loc.speed != null ? loc.speed * 3.6 : null, new Date(loc.time || Date.now()).toISOString()); }); }
      catch (e) { console.warn('driverpos watcher', e); DA.watcher = null; }
