      const imeis = list('vehicles').map(v => v.gpsId).filter(Boolean); if (!imeis.length) return (DA.vehPos = []);
      const r = await gpsCall('track', { imeis: imeis.join(',') }); const now = Date.now();
      DA.vehPos = (r.positions || []).map(p => { const v = list('vehicles').find(x => x.gpsId === p.imei); if (!v || p.lat == null) return null; const at = p.sysAt && p.at && new Date(p.at) > new Date(p.sysAt).getTime() + 60000 ? p.sysAt : (p.at || p.sysAt); const age = at ? (now - new Date(at).getTime()) / 1000 : 1e9; return { v, lat: +p.lat, lng: +p.lng, speed: p.speed != null ? +p.speed : null, moving: (p.speed != null && p.speed >= 3) || p.motion === true, fresh: age < FRESH_S && p.outdated !== true && p.valid !== false }; }).filter(Boolean);
