    const badge = !st ? `<span class="badge">${L('جارٍ الفحص…', 'Checking…')}</span>` : st.configured ? `<span class="badge ${st.lastSync ? 'good' : 'warn'}">${st.env === 'production' ? L('إنتاج', 'Production') : 'Staging'} · <span class="notr ltr">${esc(st.server || '')}</span>${st.lastSync ? ' · ' + L('آخر مزامنة', 'last sync') + ' ' + ago(st.lastSync) : ''}</span>` : `<span class="badge warn">${L('مش متوصّل لسه', 'Not connected yet')}</span>`;
