  ACTIONS.paVehicles = async () => { if (!mayView() || !hosted()) return; try { const r = await call('vehicles'); if (r.ok) { PA.vehs = r.vehicles || []; rerender(); } else toast(r.error || 'error', 'err'); } catch (e) { toast(e.message, 'err'); } };

