    const doc = Object.assign({}, x || {}, { id: (x && x.id) || uid(), kind: d.kind === 'wh' ? 'wh' : d.kind === 'fuel' ? 'fuel' : 'place', supplierId: d.kind === 'wh' ? d.supplierId : null, petro: d.kind === 'fuel' ? d.petro === '1' : undefined, fuels: d.kind === 'fuel' ? (typeof window.nfFuelListOf === 'function' ? window.nfFuelListOf(d.fuels) : []) : undefined, name: String(d.name).trim(), area, address: String(d.address || '').trim(), lat, lng, createdByName: (x && x.createdByName) || (S.session && S.session.name) || '' });
