        if (need && patch.payment === 'reimburse') { try { if (typeof pushSend === 'function') pushSend(['role:acc', 'role:hr'], L(`تموين طوارئ محتاج تسوية — ${who(x)}`, `Emergency refuel to settle — ${who(x)}`), `${x.station.name} · ${vname(x.vehicleId)} · ${L('الإيصال في السيستم', 'the receipt is in the system')}`, `/#/go/fuel/${x.id}`, 'nf-fuel-acc-' + x.id); } catch (e) { /* ignore */ } }
