    if (!(await claim(id, false))) return;
    const den = Array.from(new Set([...(t.driverDenied || []), me()]));
    local(id, t.driverId === me() ? { driverId: null, driverName: '', driverConfirmed: false, driverGuess: 'denied', driverDenied: den } : { driverDenied: den });
