function ownerNameGeneric(n) { const t = String(n || '').trim(); return !t || ['المدير', 'المالك', 'admin', 'owner', 'manager'].includes(t.toLowerCase()); }
function ownerCardKey() { try { const u = S.sbUser; const login = (u && ((u.user_metadata && u.user_metadata.login) || String(u.email || '').split('@')[0])) || (S.me && S.me.login) || ''; return login ? 'nf.ownerCard.' + login : ''; } catch (e) { return ''; } }
