    if (!ownerNameGeneric(nm) && c.name !== nm) { c.name = nm; dirty = true; }
    if (S.session.nameEn && c.nameEn !== S.session.nameEn) { c.nameEn = S.session.nameEn; dirty = true; }
    if (src && src.length < 400000 && c.avatar !== src) { c.avatar = src; dirty = true; }
