        const doc = { id: uid(), number: nextQuoteNo(), clientId, status: 'draft', date: todayISO(), validUntil: src.validUntil && src.validUntil >= todayISO() ? src.validUntil : addDays(todayISO(), 15), createdBy: (S.session && S.session.id) || null, createdAt: nowISO(), tenderId: tid, tenderName: name, copiedFrom: src.id };
