    if (o && r.siteOrder === o.id) return { ok: true, why: L('في موقع المشروع النهارده', 'At the project site today') };
    const st = oSite(o);
    if (g && st && near(g, st, st.radius || 100)) return { ok: true, why: L(`باصم في موقع المشروع ${hm(r.in)}`, `Checked in at the project site ${hm(r.in)}`) };
    if (g && o && g.zone && String(g.zone).indexOf(String(o.code) + ' ') === 0) return { ok: true, why: L(`باصم في موقع المشروع ${hm(r.in)}`, `Checked in at the project site ${hm(r.in)}`) };
    return { ok: false, why: g ? L(`باصم في: ${g.zone || 'مكان تاني'}`, `Checked in at: ${g.zone || 'another place'}`) : L('البصمة من غير موقع', 'Check-in without a location') };
