  const home = () => { try { return homeView(); } catch (e) { return 'dashboard'; } };
  const atHome = () => !S.route || (!S.route.id && S.route.view === home());
  ACTIONS.a2Back = () => {
    let prev = ''; try { prev = typeof navPrev === 'function' ? navPrev() : ''; } catch (e) { prev = ''; }
    if (prev && prev !== location.hash) { history.back(); return; }
    /* opened directly: a detail page goes up to its list, any other page to the home page */
    const up = document.querySelector('#topbar .tb-actions a[data-navback][href^="#/"]');
    location.hash = up ? up.getAttribute('href') : (S.route && S.route.id ? '#/' + S.route.view : '#/' + home());
    try { parseRoute(); } catch (e) { /* ignore */ } render(true);
  };
