    if (k !== CD.tool) CD.prevTool = CD.tool; CD.tool = k; prefs.tool = k; if (PENS.includes(k)) prefs.lastDraw = k; savePrefs(); applyTool(); if (CD.ptest && PENS.includes(k)) CD.ptest.setTool(k);
