    if (a === 'wheel') return CD.qw ? closeQW() : openQW(pt);
    if (a === 'eraser') return setTool(CD.tool === 'eraser' ? (prefs.lastDraw || 'pencil') : 'eraser');
    if (a === 'last') return setTool(CD.prevTool && CD.prevTool !== CD.tool ? CD.prevTool : (prefs.lastDraw || 'pencil'));
