    const near = (['color', 'brush', 'move', 'tools', 'prec'].includes(kind) || kind.startsWith('hub:')) && !narrow(); p.className = 'cd-pop' + (near ? ' near' + side() : '');
    p.style.left = near ? (side() === 'l' ? '260px' : 'auto') : ''; p.style.right = near ? (side() === 'r' ? '260px' : 'auto') : '';
