      p.innerHTML = hd(L('الألوان', 'Colours')) + `<div class="cd-wheel"></div>${pr ? `<div class="cd-mlbl">${esc(L('ألوان المشروع', 'Project colours'))} · <span class="notr">${esc(pr.name || '')}</span></div><div class="cd-pal">${pal.map((c, i) => `<span class="cd-pre"><button type="button" class="cd-sw" data-cd="paluse" data-k="${esc(c)}" style="--c:${esc(c)}" aria-label="${esc(c)}"></button>${canPal ? `<button type="button" class="cd-prex" data-cd="paldel" data-k="${i}" aria-label="${esc(L('شيل', 'Remove'))}">✕</button>` : ''}</span>`).join('')}${canPal && pal.length < 16 ? `<button type="button" class="cd-chip" data-cd="paladd">${IC.plus}${esc(L('ضيف اللون ده', 'Add this colour'))}</button>` : ''}</div>${!pal.length ? `<p class="cd-hint">${esc(L('ألوان المشروع بيشوفها كل فريق المشروع في كل رسوماته.', 'The project colours are shared with the whole project team in all its drawings.'))}</p>` : ''}` : ''}<button type="button" class="cd-mi" data-cd="tool" data-k="eyedrop">${IC.eyedrop}<span>${esc(L('خد لون من الرسمة', 'Pick a colour from the drawing'))}</span></button>`;
