      wh.classList.toggle('cd-fanw', tab !== 'hsl'); if (tab === 'fan') wh.innerHTML = fanHTML(); else if (tab === 'rgb') wh.innerHTML = rgbHTML(); else NFDraw.colorPicker(wh, CD.color, (hex, fin) => setColor(hex, fin));
      const rc = (prefs.recent || []).slice(0, 10); if (rc.length && tab !== 'hsl') wh.insertAdjacentHTML('afterend', `<div class="cd-mlbl">${esc(L('آخر الألوان', 'Recent colours'))}</div><div class="cd-strip">${rc.map(c => `<button type="button" class="cd-sw" data-cd="paluse" data-k="${esc(c)}" style="--c:${esc(c)}" aria-label="${esc(c)}"></button>`).join('')}</div>`);
