      pc.onconnectionstatechange = () => { const s2 = pc.connectionState; const p = st.peers.get(id); if (p) p.net = s2; if (s2 === 'failed' && o.me.id < id) { try { pc.restartIce(); } catch (e) { /* old browser */ } offer(id, true); } upd(); };
