        for (let k = 0; k < 3 && !ok; k++) { try { const r = await fn('chunk', { pid: o.me.id, name: o.me.name, t0: it.t0, t1: it.t1, audio: toB64(it.wav), mime: 'audio/wav' }); ok = !!r.ok || r.error === 'not recording'; if (r.key === false) ev('nokey'); if (!ok) await new Promise(x => setTimeout(x, 1500 * (k + 1))); } catch (e) { await new Promise(x => setTimeout(x, 1500 * (k + 1))); } }
