  ACTIONS.mtCopy = async id => { const m = byId(COL, id); if (!m) return; try { await navigator.clipboard.writeText(linkOf(m)); toast(L('اللينك اتنسخ ✓', 'Link copied ✓')); } catch (e) { prompt(L('انسخ اللينك', 'Copy the link'), linkOf(m)); } };
  const inviteText = m => `${L('اجتماع', 'Meeting')}: ${m.title}\n${m.status === 'scheduled' ? fmtWhen(m.at) + '\n' : ''}${linkOf(m)}`;
