  const closeT = async (t, note) => { try { const now = nowISO(); await Store.update('tasks', t.id, { status: 'done', doneAt: now, doneByName: me().name || 'السيستم', autoClosed: true, proof: { note, at: now, byName: me().name || '' } }, { silent: true }); } catch (e) { /* ignore */ } };
