    const ex = projFiles(pid); const taken = new Set();
    F.pid = pid; F.plan = imgs.map(f => { const m = matchOf(f, ex, taken); if (m) taken.add(m.id); return { file: f, match: m ? m.id : '', st: '', ok: false }; });
    const rows = F.plan.map((x, i) => { const m = x.match ? byId('files', x.match) : null;
      return `<div class="fnr" id="fnr${i}"><div class="fnn"><b class="notr" dir="auto">${esc(x.file.name)}</b><small class="muted"><bdi dir="ltr">${MB(x.file.size)}</bdi> · ${m ? `${esc(L('هيتبدّل مكان', 'replaces'))} <span class="notr" dir="auto">${esc(m.name)}</span>` : esc(L('ملف جديد', 'new file'))}</small></div><span class="fns ${m ? 'rep' : 'new'}">${esc(m ? L('استبدال', 'Replace') : L('جديد', 'New'))}</span><div class="fnp small muted" id="fnp${i}"></div></div>`; }).join('');
    const big = F.plan.some(x => x.file.size > MAXSB);
