  const TYPES = { ext: ['خارجي', 'Exterior'], int: ['داخلي', 'Interior'], master: ['ماستر بلان', 'Masterplan'], video: ['فيديو', 'Video'], anim: ['أنيميشن', 'Animation'] };
  const typeL = t => (TYPES[t] ? L(TYPES[t][0], TYPES[t][1]) : '');
  const DEF_ED = ['stu_sabek'];
  const P = { ed: null, asked: false, filter: 'all', year: '', busy: false };
  const myW = () => String((S.session && S.session.workerId) || (typeof stuMe === 'function' ? stuMe() : '') || '');
  function editors() { if (Array.isArray(P.ed)) return P.ed; const s = S.settings && S.settings.pfEditors; return Array.isArray(s) ? s : DEF_ED; }
  function askEditors() { if (P.asked || typeof sbOn !== 'function' || !sbOn() || !S.sb || !S.sb.rpc) return; P.asked = true; Promise.resolve(S.sb.rpc('nf_pf_editors')).then(r => { if (r && Array.isArray(r.data)) { P.ed = r.data.map(String); rerender(); } }, () => { }); }
  const canEdit = () => { if (!S.session) return false; if (typeof isAdmin === 'function' && isAdmin()) return true; askEditors(); const w = myW(); return !!w && editors().includes(w); };
  const all = () => list('portfolio').filter(e => e && !e.deleted);
  const order = arr => arr.sort((a, b) => ((+a.order || 999) - (+b.order || 999)) || String(b.updatedAt || b.createdAt || '').localeCompare(String(a.updatedAt || a.createdAt || '')));
  const shown = () => order(all().filter(e => e.published || canEdit()));
  const published = () => order(all().filter(e => e.published));
