  const coverFile = e => { const fs = shotsOf(e); return (e.coverId && fs.find(f => f.id === e.coverId)) || fs[0] || null; };
  const coverSrc = e => { const f = coverFile(e); return f ? (HQ.get(f.id) || f.thumb || '') : (e.coverUrl || ''); };
