      <div class="pfhead"><div><h2>${esc(L('شغل الاستوديو', 'Studio work'))}</h2><small class="muted">${esc(L(`${published().length} مشروع منشور`, `${published().length} published projects`))}${ed ? ` · ${esc(L(`${es.length - published().length} مسودة`, `${es.length - published().length} drafts`))}` : ''}</small></div><div class="grow"></div>
        ${ed ? `<button type="button" class="btn p sm" data-action="pfNew">${icon('plus')}${esc(L('مشروع قديم', 'Old project'))}</button>` : ''}${isAdmin() ? `<button type="button" class="btn sm" data-action="pfEditors">${esc(L('مين يعدّل', 'Who edits'))}</button>` : ''}</div>
