      <div class="pfinfo">${rows.length ? `<dl>${rows.map(r => `<div><dt>${esc(r[0])}</dt><dd class="notr" dir="auto">${esc(String(r[1]))}</dd></div>`).join('')}</dl>` : ''}${e.about ? `<p class="notr" dir="auto">${esc(e.about)}</p>` : ''}<div class="pflinks">${e.behance ? `<a class="btn xs ghost" href="${esc(e.behance)}" target="_blank" rel="noopener">${icon('link')}Behance</a>` : ''}${p && (typeof stuProjectVisible !== 'function' || stuProjectVisible(p)) ? `<a class="btn xs ghost" href="#/projects/${esc(p.id)}">${esc(L('افتح المشروع', 'Open the project'))}</a>` : ''}</div></div>
