  const B2 = (ar, enx) => `${ar}<small class="sdx">${enx}</small>`;   /* the sheets are bilingual on paper */
  const MONEY = /(\d[\d.,\s]*\s*(جنيه|ج\.?م|EGP|LE|USD|\$|دولار|ريال|SAR|€))|((EGP|USD|SAR|\$|€)\s*\d[\d.,]*)/gi;
  const nm = () => (S.session && S.session.name) || '';
