  const dmy = iso => { if (!iso) return '—'; const d = String(iso).slice(0, 10).split('-'); return d.length === 3 ? `${d[2]}/${d[1]}/${d[0]}` : iso; };
  const num2 = v => (typeof fmtNum === 'function' ? fmtNum(v) : String(v));
