    const upd = Object.assign({}, m, v.fields || {}, { ver, versions: (m.versions || []).concat([snap]).slice(-40) }); upd.tlog = withLog(Object.assign({}, m, { ver }), 'restored', `v${v.ver} → v${ver}`);
