    if (b) parts.push(`${esc(L('ماراجعش المصنع — كمّل لمشوار', "Didn't go back to the factory — went on to trip"))} <a href="#/fleet/${esc(b.id)}"><b>${esc(b.number || '')}</b></a>${toName(b) ? ` (${esc(toName(b))})` : ''}`);
