  window.nfHeadDepts = () => { try { if (!S.session || role() === 'head' || SEES_ALL.includes(role()) || role() === 'kiosk') return []; return hdOf(meW()); } catch (e) { return []; } };
  window.nfXHeadsOf = d => (d ? list('workers').filter(w => active(w) && hdOf(w).includes(d)) : []);
