  ACTIONS.nflUi = () => { const on = uiOn(); lss(K_UI, on ? 'off' : null); toast(on ? L('اتقفل — الرئيسية رجعت زي ما كانت', 'Off — the home page is back as it was') : L('اتفتح', 'On')); rerender(); };
