        body += sec(L('أنماط الشغل', 'Work patterns'), vOps(o), L('آخر 90 يوم.', 'The last 90 days.'));
        body += sec(L('استخدام الواجهة — المجموع', 'Use of the screens — totals'), vUi(o), L('مجموع من غير أسامي.', 'Totals, with no names.'));
