  const jget = k => { try { return JSON.parse(lsg(k) || '{}') || {}; } catch (e) { return {}; } };
  const viewing = () => typeof isViewing === 'function' && isViewing();
  const person = () => !!S.session && role() !== 'kiosk' && !viewing() && (typeof window.nfTwinOk !== 'function' || window.nfTwinOk());   /* v7.79: the studio twin is for the two of them only */
