    if (f.ownerKind === 'task') { const t = byId('tasks', f.ownerId); if (!t) return ''; if (/^inst/.test(String(t.deptId || '')) || /تركيب/.test(String(t.title || ''))) return 'ins'; return /مشوار تسليم|تسليم/.test(String(t.title || '') + String(f.note || '')) ? 'dlv' : ''; }
